local _, WFJ = ...
WFJ.Data.add("quest", {
  [7003] = { "縮められた巨人", "Feralasにいるいずれかの種類の巨人を縮めるためZorbin's Ultra-Shrinkerを使い、扱いやすい姿へ変えて下さい。いずれかの巨人から発見したMiniaturization Residue 15個を、FeralasのForgotten Coastの桟橋にいるZorbin Fandazzleに渡して下さい。", "ここに居座るなら、巨人どもを何とかしないとな！商売に良くないのは確かだろう？\n\nノームの縮小光線を改良したものを作ってるんだが、組み立てには優れたGOBLINの先端技術を使ってるんだ！死ぬみたいな不都合を自分で被らないように、Feralasの巨人どもで試してきてほしいんだよ。縮めた後の奴らからminiaturization residueが見つかるはずだ。いくらか持ち帰ってくれ！", "Miniaturization residueはね、断言するけど、工学においては貴重な品なんだ！まあ、貴重というのは、光線銃が使用者の目の前で爆発するなんていう残念なことにならないようにするのに役立つ、という意味でね。\n\nああ、つまり君に渡した以外の光線銃の話だよ。もちろんさ！", "スンバラシイ! 残留物を持って帰ってきてくれたのはもちろん、手足も大事なところも全部無事なのがうれしいよ! まあ、その、Ultra-Shrinkerを使うのに危険なんてこれっぽっちもなかったんだけどね!\n\n私のために頑張ってくれて本当に感謝してるよ、{name}。まったく、あんたは世界中のゴブリンの友だ。感謝のしるしにこれを受け取っておくれ!", 0x236b774b, 0xee4452cf, 0x95a0e065, 0xfba8b795, 0xfdd0c9ae, "....." },
  [7021] = { "Great-father Winterがやってきた!", "Greatfather Winterと話して下さい。彼はOrgrimmarのSmokywood Pastures露天商市場にいます。", "友よ、素晴らしいWinter Veilを! 必ず今OrgrimmarにいるGreatfather Winterに挨拶して下さいね! 今年あなたが親切だったなら、Winter Veil祝祭日の素晴らしいご馳走を受け取れるでしょう。今年欲しい物を彼に伝えるのもお忘れ無く!\n\nあと、今年親切にしてくれた人にあげるご馳走を買い込むのもお忘れ無きよう。選ぶ物は豊富に取り揃えていますよ。私たちの農場から、あなたのお皿まで新鮮なものを……それがSmokywood Pasturesの健康に良い美味しさ!", nil, "はいどう、どう。こんにちは。私はGreatfather Winter。それと、気の良いSmokywood Pasturesの人々からの厚意……「私たちの農場からあなたのお皿へ新鮮なものを。それがSmokywood Pasturesの健康に良い美味しさ」……Winter Veilの素晴らしい祝祭があなたに訪れますように。\n\n今年あなたが良い人だったなら、Winter Veil祝祭のご馳走としてSmokywood Pasturesのご馳走を受け取れるでしょう。ばんざい。", 0x9a9ce503, 0x591cc909, 0x68b6c09d, nil, 0x296b27e3, "...m." },
  [7022] = { "Greatfather Winterがやってきた!", "Greatfather Winterと話して下さい。彼はIronforgeのSmokywood Pastures露天商市場にいます。", "友よ、素晴らしいWinter Veilを! 必ずGreatfather Winterに挨拶して下さいね! 今年あなたが親切だったなら、Winter Veil祝祭日の素晴らしいご馳走を受け取れるでしょう。今年欲しい物を彼に伝えるのもお忘れ無く!\n\nあと、今年親切にしてくれた人にあげるご馳走を買い込むのもお忘れ無きよう。選ぶ物は豊富に取り揃えていますよ。私たちの農場から、あなたのお皿まで新鮮なものを……それがSmokywood Pasturesの健康に良い美味しさ!", nil, "はいどう、どう。こんにちは。私はGreatfather Winter。それと、気の良いSmokywood Pasturesの人々からの厚意……「私たちの農場からあなたのお皿へ新鮮なものを。それがSmokywood Pasturesの健康に良い美味しさ」……Winter Veilの素晴らしい祝祭があなたに訪れますように。\n\n今年あなたが良い人だったなら、Winter Veil祝祭のご馳走としてSmokywood Pasturesのご馳走を受け取れるでしょう。ばんざい。", 0xddbfaa79, 0x01d48083, 0xba4aa7ab, nil, 0x296b27e3, "...m." },
  [7023] = { "Greatfather Winterがやってきた!", "Greatfather Winterと話して下さい。彼はIronforgeのSmokywood Pastures露天商市場にいます。", "友よ、素晴らしいWinter Veilを! 必ず今IronforgeにいるGreatfather Winterに挨拶して下さいね! 今年あなたが親切だったなら、Winter Veil祝祭日の素晴らしいご馳走を受け取れるでしょう。今年欲しい物を彼に伝えるのもお忘れ無く!\n\nあと、今年親切にしてくれた人にあげるご馳走を買い込むのもお忘れ無きよう。選ぶ物は豊富に取り揃えていますよ。私たちの農場から、あなたのお皿まで新鮮なものを……それがSmokywood Pasturesの健康に良い美味しさ!", nil, "はいどう、どう。こんにちは。私はGreatfather Winter。それと、気の良いSmokywood Pasturesの人々からの厚意……「私たちの農場からあなたのお皿へ新鮮なものを。それがSmokywood Pasturesの健康に良い美味しさ」……Winter Veilの素晴らしい祝祭があなたに訪れますように。\n\n今年あなたが良い人だったなら、Winter Veil祝祭のご馳走としてSmokywood Pasturesのご馳走を受け取れるでしょう。ばんざい。", 0xddbfaa79, 0x01d48083, 0x79ea1c26, nil, 0x296b27e3, "...m." },
  [7024] = { "Great-father Winterがやってきた!", "Greatfather Winterと話して下さい。彼はOrgrimmarのSmokywood Pastures露天商市場にいます。", "友よ、素晴らしいWinter Veilを! 必ず今OrgrimmarにいるGreatfather Winterに挨拶して下さいね! 今年あなたが親切だったなら、Winter Veil祝祭日の素晴らしいご馳走を受け取れるでしょう。今年欲しい物を彼に伝えるのもお忘れ無く!\n\nあと、今年親切にしてくれた人にあげるご馳走を買い込むのもお忘れ無きよう。選ぶ物は豊富に取り揃えていますよ。私たちの農場から、あなたのお皿まで新鮮なものを……それがSmokywood Pasturesの健康に良い美味しさ!", nil, "はいどう、どう。こんにちは。私はGreatfather Winter。それと、気の良いSmokywood Pasturesの人々からの厚意……「私たちの農場からあなたのお皿へ新鮮なものを。それがSmokywood Pasturesの健康に良い美味しさ」……Winter Veilの素晴らしい祝祭があなたに訪れますように。\n\n今年あなたが良い人だったなら、Winter Veil祝祭のご馳走としてSmokywood Pasturesのご馳走を受け取れるでしょう。ばんざい。", 0x9a9ce503, 0x591cc909, 0x68b6c09d, nil, 0x296b27e3, "...m." },
  [7025] = { "Greatfather Winterへのおやつ", "Gingerbread Cookie 5枚とIce Cold MilkをIronforgeのGreatfather Winterに渡して下さい。", "やあ、頼んでいいかな? ええと、おちびさん。\n\nわざわざ自分のことを三人称で言うつもりはないけど、Greatfather Winterは一日中ここにいて腹ぺこだから、自分で食べるおやつが必要なんだ。gingerbread cookiesを少し、それとクッキーを流し込むice cold milkがあったらいいなあ。君がGreatfatherの友達だと思うなら、いくつか取ってきてくれないかな?", "お菓子の話ばかりしていたら、自分でも食べたくなってきたよ。うーん……gingerbread cookiesとmilk……", "{name}、君はGreatfather Winterじいさんのいいお手伝いさんだね。素敵なWinter Veil祝祭を楽しんでね。\n\nささやかなものだけど……そうだよ、お礼にあげよう。", 0xec79af5f, 0x98d20954, 0x6341ef2b, 0x11c73f24, 0x004980cd, ".....", nil, nil, 0xcc6e16c8, nil, nil },
  [7028] = { "歪んだ悪の源", "DesolaceのWillowのために、Theradric Crystal Carving 25個を集めて下さい。", "Terramokの水晶の洞窟は西、Maraudonの奥深くにある……長い歴史を持つ古の地だ。そしてその歴史の一部を手に入れたいと思っているのだよ、{class}。巨大な扉の向こうには古の神々の遺物が隠されている。\n\nMaraudonに潜む歪んだ悪に立ち向かう気があるなら、君の手間に見合うだけのことはしよう。見つけたtheradric crystal carvingsを集めて、私のところへ持ってきてくれ。\n\ncarvingsが手に入れば、私は……それを研究できる。あの力はあまりに長く眠りすぎたのだ……", "質問するな！\n\n頼みはもう伝えたはずだ。", "ハハハ! 戻ってくると分かっていたぞ。\n\n<Willowがつぶやく。>\n\n……実にたやすく言いくるめられる。\n\n……相応の値さえ出せば何でもやる。ヘヘヘ……", 0xeb949bcd, 0x2ae5de19, 0x1db4989e, 0x6691d3a6, 0xc35764ff, "....." },
  [7029] = { "Vyletongueの腐敗", "MaraudonにあるオレンジのクリスタルのプールでCoated Cerulean Vialを満たす。\n\nFilled Cerulean VialをVylestem Vinesに使い、堕落したNoxxious Scionを出現させる。\n\nこのNoxxious Scionを倒して植物を$N1本癒し、Shadowprey VillageのVark Battlescarのところへ戻って下さい。", "Vyletongueと呼ばれるsatyrがMaraudonの洞窟を穢し、中の多くの植物の成長を妨げています。\n\nこのvialを持って行ってください、{name}。洞窟の中にあるオレンジ色の水晶の池で満たすのです。vialの内側の被膜が毒を打ち消し、癒しの薬に変えてくれます。\n\nオレンジの洞窟の中にあるVylestem vinesを見つけて、浄化した液体をかけてください。植物から穢れは祓われますが、Vyletongueが今もそれを操っていることは覚えておいてください。あなたに差し向けてくるかもしれません……", "この植物を癒すことができれば、再び成長し始めるでしょう。できることをしなければなりません、{name}……", "これを返してくれてありがとうございます、{name}。持ってきてくれた残りの液で、私は研究を続けられます。\n\nまだやるべきことは多く残っていますが、あなたはVyletongueがMaraudon中に広げた汚染の一部を癒す助けとなりました。どうか感謝とともにこれを受け取ってください。", 0x7d91904f, 0x0bfd4158, 0xe082ee66, 0x364cece8, 0x5d10207c, "....." },
  [7041] = { "Vyletongueの腐敗", "MaraudonにあるオレンジのクリスタルのプールでCoated Cerulean Vialを満たす。\n\nFilled Cerulean VialをVylestem Vinesに使い、堕落したNoxxious Scionを出現させる。\n\nこのNoxxious Scionを倒して植物を$N1本癒し、Nijel's PointのTalendriaのところへ戻って下さい。", "Vyletongueと呼ばれるsatyrがMaraudonの洞窟を穢し、中の多くの植物の成長を妨げています。\n\nこのvialを持って行ってください、{name}。洞窟の中にある穢れたオレンジ色の池で満たすのです。vialの内側の被膜が毒を打ち消し、癒しの薬に変えてくれます。\n\nオレンジの洞窟の中にあるVylestem vinesを見つけて、浄化した液体をかけてください。植物から穢れは祓われますが、Vyletongueが今もそれを操っていることは覚えておいてください。あなたに差し向けてくるかもしれません……", "この植物を癒すことができれば、再び成長し始めるでしょう。できることをしなければなりません、{name}……", "これを返してくれてありがとうございます、{name}。持ってきてくれた残りの液で、私は研究を続けられます。\n\nまだやるべきことは多く残っていますが、あなたはVyletongueがMaraudon中に広げた汚染の一部を癒す助けとなりました。どうか感謝とともにこれを受け取ってください。", 0x7d91904f, 0xf4e77a61, 0xfab7c5bd, 0x364cece8, 0x5d10207c, "....." },
  [7042] = { "盗まれたWinter Veilのご馳走", "Alterac Mountainsの雪国で行方不明になったSmokywood Pastures捜査官を捜して下さい。", "聞いて下さい……ここで季節の魔法を壊さないために。でも、Smokywood Pasturesには少し手助けが……あなたのような冒険型の人に助けてもらう類の手助けが、必要なんです。\n\nこの季節のために私たちが仕入れ直した、大事なご馳走の積荷が無くなってしまいました。そして、積荷を探すために送り出したSmokywood Pasturesの者までが行方不明になってしまったんです! お願いします……積荷が最後に報告されたのはAlterac Mountainsでした。積荷を探しに行った者がいるのもそこなんです。\n\n両方ともそこで無事で元気にしているかどうか、見てきて下さい!", nil, "ききき聞こえるか! ここここの結末に感謝だ!\n\nほんとのススススノウマンじゃないぞ、私のななな名前はSacks。Smokywood PasturesのIronforgeししし支部で、ははは働いているんだ……。ななな無くなった小包を探しにここへおおお送り出されたら、いいい今まで見たこともないいいい生き物に攻撃されたんだ!\n\nすすすすごく寒いよ……", 0x3874de93, 0xfed7fa48, 0x497a89c9, nil, 0xe02f2537, "...m." },
  [7043] = { "あんたは意地悪な奴だ……", "Stolen Treatsを探してIronforgeのWulmort Jinglepocketに返して下さい。最終的に所持していると思われるのはAbominable Greenchです。その獣はAlterac Mountainsの雪国のどこかにいます。", "「Abominable Greench」というそのいいい生き物は、積荷のごごごご馳走を盗んだややや奴なんだ、{name}。だがききき気をつけろ! ああああいつ、私をゆゆゆ雪だるまにしやがったんだ!\n\n奴にたたた立ち向かうのに、手伝いがいるだだだだろう。私は奴がイイイイエティのいるそこら中をあああ歩き回ってるのを見たんだ。奴はたたた確かにここのどどどどこかにいる! ご馳走をみみみ見つけてくれ、{name}。ご馳走をIronforgeのSmokywood Pasturesにかかか返して、解凍してほほほほしいと言っていたとつつつ伝えてくれ!", "{name}、補充するtreatsがなければ、私たちのFeast of Winter Veilは台無しだ！今シーズンはGraccu本人も、いい子のみんなにおいしいミートパイを分けてあげられなくなってしまう……", "見つけてくれたのですか! あなたはSmokywood PastureのWinter Veilのご馳走を守って下さった!\n\n可哀想なSacks……私たちはチームを送って、確実に彼の凍結を解除する方法を見つけ出すつもりです。うまくいけば、彼は祝祭日に間に合うように戻ってこられるはず。もっとも、失った時間は働きながら取り戻す必要があるでしょうけど。でも、あなたがいなかったら、それすら不可能だったでしょうね!", 0xdc4f5e6e, 0x8c241804, 0x01913b07, 0x5cb087ef, 0x84619c0c, "....." },
  [7044] = { "Maraudonの伝説", "Scepter of Celebrasの2つの部品、Celebrian RodとCelebrian Diamondを回収する。\n\nCelebrasと話す方法を見つけて下さい。", "Lord Vyletongueという闇のsatyrが、この曲がりくねった洞窟に悪を広め、中にいるすべての者の心を毒しました。彼は今も紫の水晶の向こうに棲んでいます。\n\nVyletongueはまた、自らの穢れの生きた象徴としてNoxxionというものを生み出し、それはオレンジの水晶の向こうに潜んでいます。彼らは二人で、兄の笏の二つの部品を奪い取ったのです。兄のCelebrasは……穢れに呪われ、中を盲目的にさまよっています。\n\n兄を助けてください！部品を見つけて、兄と話してください……どうにかして。", "終わることがないように思えた悪夢から、ようやく目覚めた……", "私の杖のパーツをふたつとも取り戻してくれたのだね。いつの日かMaraudonはVyleの腐敗を排除できるという希望がもてる。", 0x9af58870, 0xf9e13397, 0x41cb6b05, 0x82ff0f35, 0x9c0b7265, "....." },
  [7045] = { "Smokywood Pasturesのありがとう!", "IronforgeでGreatfather Winterと話して下さい。", "私たちSmokywood Pasturesの者は、盗まれたご馳走を取り戻して下さったことに感謝しています、{name}。それで、あなたに特別な贈り物を差し上げたいのです……他ならぬ、Greatfather Winterその人から!\n\nどうぞGreatfather Winterと話して下さい。Smokywood PasturesからのWinter Veil祝祭の贈り物をあなたにくれるでしょう。私たちの農場から皆さんのお皿まで、それはいつもSmokywood Pasturesの健康に良い美味しさ。……あなたのおかげです、もちろん!", nil, "はいどう、どう。こんにちは、冒険者さん!\n\n今年の休暇シーズンの特別な贈り物はあなたが獲得したとゴブリンから聞きました。これを贈ることができて嬉しいですよ。お待ちどお。……今後とも、今年も来年も再来年も、毎年Winter Veilの素晴らしい祝祭を楽しんで下さいね。", 0xfdb1c16f, 0x466d6e14, 0x1ebc2085, nil, 0xc8c04af1, "...m." },
  [7046] = { "Scepter of Celebras", "Celebras the RedeemedがScepter of Celebrasを作る間、彼を手助けする。\n\n儀式が終わったら彼と話して下さい。", "私の笏は、かつて私にとって希望の源だった。その力のおかげで、私はこの洞窟を素早く行き来する自由を得ていたのだ。叔父の霊に安らぎをもたらしたいと願っていた……その務めを、今あなたに託そう。\n\n二つの部品を再び一つにするには、儀式を行うのにあなたの助けが必要だ。どうかついてきて、私がrodとdiamondを再び結び合わせるのに必要な力を注ぐ間、私の指示を聞いてほしい。\n\n共に、再びScepter of Celebrasを作り上げよう！", "儀式をやり直したいのなら、最初の試みを放棄してから、もう一度私に話しかけてください。", "どうかこれを受け取ってほしい。そして今そなたに託されたこの力は、善きことのために使わねばならぬと知っておくがいい。洞窟の奥へと旅を続けよ。願わくは、我が叔父の亡骸を見つけられるだろう。多くの危険がそなたを待っている、{name}。\n\n必要が生じたなら、再び我に話しかけるがよい。", 0x8ee6a5f3, 0xa2c0701f, 0xdf0c447d, 0x4b5207a1, 0xada0789a, "....." },
  [7061] = { "The Feast of Winter Veil", "この休日について詳しく知るために、「The Feast of Winter Veil」を自由に読んで下さい。本を読み終えたら、Thunder BluffのCairne Bloodhoofに届けて下さい。", "さあ、Winter Veilの祝祭をもっと詳しく知りたいなら、この本を読んでくれ。伝説についての我々の認識は正しいものだと思うがね。私はひとつにまとまった伝承集を正しく理解する大の伝説研究家なんだ。\n\n読み終わったら、Thunder BluffのCairne Bloodhoofのところへこの本を持って行ってくれ。我々の伝承に興味を抱く者がいたと聞くことにCairneが関心を持つだろうと分かっているからな。", "Mulgore、そして私たちのささやかな集落Thunder Bluffへようこそ、友よ。私は、この王国とその民、その伝承に関心を寄せる者に、いつも関心を持っているのです。あなたが私の前に立っているのも、そのためですか？", "年々、Winter Veilを取り巻く伝説や伝承は大衆の心から消えていこうとしておる。そう、あのゴブリンたちが自分たちの目的のためにこの季節を蘇らせようと力を尽くしていると、私は知っておるのだ。我が民がとにかく何らかの形でそれに思いを馳せるという事実は、そういった伝承を語り継いでいくには良いことだ。\n\n物欲を越え、我らの過去について学ぼうというそなたの希求は賞賛に値する特徴だな。若き{class}よ。そなたの英知に敬意を表する。", 0xe673c3f4, 0x05622809, 0x0f6ff760, 0x35cce9a8, 0xb689b4a4, "....." },
  [7062] = { "祝祭の季節の由来", "Winter Veilの祝祭について、IronforgeのExplorer's LeagueにいるHistorian Karnikと話して下さい。", "贈り物に、ご馳走に、プレゼント……ふん。くだらん!\n\nあのゴブリンたちはこの季節の本当の意味を汚しているよ。……Winter Veilの祝祭を。これは再生の時なんだ。大地はGreatfather Winterによって生み出された雪の毛布の下でまどろむ。……Greatfather Winterは、赤い衣装を着てあっちでブツブツ言ってる馬鹿なんかじゃないんだ!\n\nこの祝祭に関するすべてのことを知りたいと思ったなら、Explorer's LeagueにいるHistorian Karnikに聞いてみるといい。プレゼントをもらうことより歴史のことを知りたいという者に驚くに違いないよ。", nil, "Winter Veilの祝祭だって? ああ……昔、それは我々ドワーフにとって深い意味を持ったものだったんだ。今では、Greatfather Winterの伝説も飴玉やプレゼントを売るのに役立つ日か何かに誰かが変えてしまったようだがな。\n\nそういう変わり方に対して、Goliが苦々しく思っていたとしても不思議じゃない。そういったドワーフたちは、戦旗のように過去にしがみついているんだ。ちょっとしたお祝いってのは、いつもいいものだ。だが、祝祭の起源を覚えておくことは大切だよ。", 0x64e6e152, 0x703c0a33, 0x2a88d079, nil, 0xeebd4aa1, "...m." },
  [7063] = { "The Feast of Winter Veil", "この休日について詳しく知るために、「The Feast of Winter Veil」を自由に読んで下さい。本を読み終えたら、Ironforge の King Magni Bronzebeard に届けて下さい。", "さあ、Winter Veil の祝祭をもっと詳しく知りたいなら、この本を読んでくれ。伝説についての我々の評価は正しいものだと思うがね。私はひとつにまとまった伝承集を正しく理解する大の研究者なんだ。\n\n読み終わったら、King Magni Bronzebeard のところへこの本を持って行ってくれ。古い伝説に興味を抱く者がいたと聞くことに彼が関心を持つだろうと分かっているからな。", "Kingdom of Ironforgeへようこそ、友よ。私は、この王国とその民、その伝承に関心を寄せる者に、いつも関心を持っているのです。あなたが私の前に立っているのも、そのためですか？", "年々、Winter Veil を取り巻く伝説や伝承は大衆の心から消えていこうとしている。あのゴブリンたちが自分たちの目的のためにこの季節を蘇らせようと力を尽くしていることは知っている。市民がとにかく何らかの形でそれに対して考えるという事実は、そういった伝承を語り継いでいくには良いことだ。\n\n物欲を越え、我らの過去について学ぼうというお主の希求は賞賛に値する特徴だな。若き{class}よ。お主の学究的本質に敬意を表する。", 0xe673c3f4, 0x836487fd, 0x99477be7, 0x6d6ae1e2, 0x335365c7, "....." },
  [7064] = { "大地と種の腐敗", "Princess Theradrasを葬り、DesolaceのShadowprey VillageにいるSelendraのところへ戻って下さい。", "Maraudonの深淵には混沌の生物が住んでいるのです……Princess Theradrasは、古き神々と繋がりを持っている大地のエレメンタル。随分昔、彼女とCenariusの長男Zaetarは恋愛関係となりました。彼らが共に過ごした時間の子孫が、Kalimdorの人々にcentaurとして知られるようになったのです。感謝することのない生き物centaurはZaetarを殺害し、そして今Zaetarの遺骨を保管しています。ここでの私の役目は、Theradrasを殺すことのできる強い者たちを探すこと。私たちがStonetalonへ帰還する前に、Zaetarの遺骨を手に入れられるかもしれないので。", "この戦いは我々だけで戦いたいところだが、他に手段は残されていない。より強い者の力が必要なのだ。そしてAzerothの種族たちは、力を合わせればこうしたものを乗り越えられると、疑いの余地なく示してきた。だからこそ、我々はそなたに助けを求めるのだ。\n\nそれで足りることを願うばかりだ。\n\nRemulosの兄弟であるZaetarは、この世界に多くの苦しみをもたらし、ついにはそれが自らの死を招いた。そなたに助力を求めたことで、さらなる死を招いていなければよいのだが。", "これは実に素晴らしい知らせです、{name}! ありがとう!\n\nMarandisと話し、Zaetarの亡骸についての知恵を仰ぐとしましょう。ですが少なくとも、あなたは最も困難な務めを乗り越えてくれました。\n\n我々の任務が成功したなら、助力してくれた者に報いる許しを得ていると言われていました。この品々は我らの民からの証として預かったものです。一つ選んでください。", 0xf63286e3, 0x39812881, 0xa03316b0, 0x5dd13056, 0x57b19b51, "....." },
  [7065] = { "大地と種の腐敗", "Princess Theradrasを葬り、DesolaceのNijel's PointにいるKeeper Marandisのところへ戻って下さい。", "Maraudonの深淵には混沌と邪悪の生物が住んでいる、{name}。Princess Theradrasは、どういうわけか古き神々と繋がりを持っている大地のエレメンタルなのだ。随分昔、彼女はCenariusの長男Zaetarに見出された。ふたりの……恋愛関係から生まれた子孫が、centaurとして知られる生き物だ。感謝することのない生き物centaurは、Zaetarを殺害し、そして今はTheradrasが彼の遺骨を保管している。ここでの私の役目は、Theradrasを殺すことのできる強い者たちを探すこと。我らがStonetalonへ帰還する前に、Zaetarの遺骨を手に入れられるかもしれないのでな。", "定命の種族たちに我が願いを押しつけることの重みは感じているが、他に手段は残されていない。Azerothの種族たちは、力を合わせればこうしたものを乗り越えられると、疑いの余地なく示してきた。だからこそ、我は彼らに助けを求めるのだ。\n\nそれで足りることを願うばかりだ。\n\nRemulosの兄弟であるZaetarは、この世界に多くの苦しみをもたらし、ついにはそれが自らの死を招いた。それを見抜くだけの賢さがあれば、そこには我ら皆にとっての教訓がある。", "これは実に素晴らしい知らせです、{name}! ありがとう!\n\nZaetarの亡骸を持ち帰れなかったことは気がかりですが、Cenariusの長子の意志に異を唱えるなど、私の身に過ぎたことです。これでcentaurの意志も挫け、血への渇きも和らぐかもしれません。そう願うほかありません。\n\n任務が成功したなら、助力してくれた者に報いるようにと、この品々を預かっていました。感謝の証として一つ選んでください。", 0xf63286e3, 0x7c3b8219, 0x4160b7a5, 0x014b5981, 0xc549a228, "....." },
  [7066] = { "Seed of Life", "MoongladeのRemulosを探し、Seed of Lifeを渡して下さい。", "道を誤ったcentaur――我が息子や娘たち――には、父が必要なのだ。\n\n周りを見てごらん――この場所は希望に満ち、我が父Cenariusの説くすべてが響いている。それは私から生まれたのだ！彼らからそれを奪うことはできない……私に対する罪があろうとも。\n\nだが、兄の心を安らげるために、一つだけ頼みたいことがある。これを持っていってくれ……私の亡骸が育んだ命から落ちた最初のseedだ。私の魂はここに留まり、私は生き続けていると兄に伝えてほしい。きっと分かってくれるだろう。", "そなたからは堕落の匂いがする、{name}……近頃の多くの冒険者と同じようにな。だが、そなたには何か違うところがある。我に話しに来たことがあるのか？そなたの纏う気配には覚えがあるようだが、どこで感じたのか思い出せぬ。\n\n頼む、どうか教えてくれ。なぜ我との謁見を求めたのだ。", "では兄はついに安らぎを得たのですか? この日を見るまで生きられたことを誇りに思います。あの傲慢さと怒りの中で、彼は本当に我々のもとから失われたのだと思っていました。ですがこれは……彼の犠牲を示すこの証は、彼が失われてなどいないことを示すばかりです。彼はただ生まれ変わったのです。彼は務めであったとおり、自然の中に己の場所を得たのです。\n\nありがとう、{name}。これを私のところへ届けてくれたことで、あなたは一度は失ったと思っていたささやかな希望を守ってくれました。この種はいつか、この戦に引き裂かれた地の民にとって大切なものとなるでしょう……そう感じられるのです。", 0xe1cc854f, 0xd69615e8, 0x3d27e50c, 0xd29e327e, 0x9f7959fd, "....." },
  [7067] = { "The Pariah's Instructions", "Pariah's Instructionsを読んで下さい。その後、MaraudonでAmulet of Unionを手に入れ、Desolace南部のCentaur Pariahに返して下さい。", "異端者として追放された身だが、私の信念は今も正しい――それだけが私を前へと駆り立てる。だが私の運命を全うするには、外の者の助けが要る……どのcentaurの部族にも属さぬ者のな。\n\nこの務めには、Maraudonの聖なる広間に入る者が必要だ――我が民が守る墓所であり、最も敬虔な者しか入ることを許されぬ場所だ。\n\n手を貸してくれるなら、ただ頷くだけでよい。指示を記した羊皮紙を渡そう。目を通し、私の言葉をよく考えてくれ。", "どう決めた、{name}？俺に手を貸してくれるか？聖なる地に足を踏み入れ、1つの偉大なcentaur部族を築くのを手伝ってくれるか！？", "これだ、{race}! これだ! これでようやく、部族を一つにまとめるという大事業を始められる。感謝する。\n\n働きに対してこれを受け取ってくれ。次に会うときは、まるで違う状況であることを願う。", 0xd8aa8c13, 0x644fa901, 0x17cdfc7b, 0xa3331956, 0x76f3983f, "....." },
  [7068] = { "Shadowshard Fragments", "MaraudonでShadowshard Fragment 10個を集め、OrgrimmarのUthel'nayに渡して下さい。", "強い魔力がcentaurの聖地に……Maraudonの聖地にあるんだ。Desolaceのcentaurの部族どもは命がけであそこを守っとるが、俺たちが要るもんを奪うのは止められねえ。\n\nお前、そのMaraudonって所へ行って、shadowshardでできた岩の化け物を見つけてこい。紫の水晶を持ってくりゃ、Uthel'nayが手間賃に何か作ってやるぞ。\n\nあそこは危ねえから、仲間を連れてった方がいいかもしれねえな。", "結晶はもう見つけたか？力の儀式に、強大な呪文……あのshadowshardsは、あらゆる秘術にすごく役立つかもしれないぞ。", "ああ、俺にとっちゃ完璧なもんだ。さあ、この飾り物からひとつ取ったら帰んな……研究せにゃならんものがたくさん手に入ったぞ。", 0xc66ff161, 0xa2e2dbe6, 0x385bc6e0, 0xcae8139d, 0x09e2939a, "....." },
  [7070] = { "Shadowshard Fragments", "MaraudonでShadowshard Fragment 10個を集め、Dustwallow Marshの海岸にあるTheramoreのArchmage Tervoshに渡して下さい。", "最近、さまざまな水晶とその秘術的な性質を試し始めたんです。Lady Proudmooreから、Desolaceへ向かう旅人にMaraudonという場所を探すよう頼んでよいとお許しをいただきました。その荒れ果てた神殿の中には、私がshadowshardsと名付けた紫がかった石でできた巨大なエレメンタルがいるのです。\n\nそちらへ向かって水晶をいくつか見つけてくださったら、とてもありがたいです。お望みなら、それで装身具を作って差し上げることもできますよ。", "もう行ってきたか？ かなり危険なのは分かっているが、うまくいけば、それだけの価値は十分にあるはずだ。", "これは完璧だ、{name}。あそこへ行って戻ってきた冒険者たちも実際にいたから、結晶でこれを作ることができたんだ……どうぞ、難しい仕事のお礼に遠慮無くひとつ取ってくれ。それと、研究用のサンプルを増やしてくれて本当にありがとうな。", 0xc66ff161, 0xec999ae3, 0x8f09c391, 0x23f22516, 0x340dad0c, "....." },
  [7081] = { "Alterac Valleyの墓地", "墓地を急襲し、Alterac MountainsのSergeant Durgen Stormpikeのもとへ戻って下さい。", "Alterac Valleyの墓地は重要な拠点だ。Horde、Alliance双方ともに、この神聖な場所のために獰猛に戦う。{name}よ、戦う準備はできたかね?\n\n君に、墓地の敵を急襲して欲しい。中央にHordeの軍旗が掲げてある墓地を探し、地面に軍旗を引きずり下ろせ! それをやれば、君の任務は完了だ....\n\nしかし、もし君が墓地を数分間保持することもできれば、我らの兵がすぐに君の代わりに駆けつけるだろう。", "{name}、まだ墓地を襲撃していないな。この任務を果たしたら戻ってこい！", "よくやった! 墓地はAlterac Valleyの支配に欠かせない。ひとつ奪うごとに、ここでのAllianceの主権を確かなものにする助けとなるのだ。\n\nさあ行け、{name}。戦いに戻り、Hordeの支配下にある墓地を見つけたら……やるべきことは分かっているな!", 0x0ef1232d, 0xee980018, 0x60742525, 0x6410f753, 0xa806e851, "....." },
  [7082] = { "Alteracの墓地", "墓地を攻撃し、Alterac MountainsのCorporal Teeka Bloodsnarlのところへ戻って下さい。", "Alterac Valleyの戦線は常に変わる。敵との死闘によって、領地は前後に行ったり来たりする。そして墓地だ、{name}。墓地で戦いは熾烈を極める。\n\nAllianceの所有する墓地を攻撃してもらいたい! Allianceの旗が真ん中にある墓地を発見し、地面から引き抜くのだ。\n\nそうしたら、任務は完了となる。が……そのまま墓地に数分留まれば、そこは我らのものとなり、部隊がやって来てお前と交代してくれる。", "Allianceが占拠する墓地を攻撃せよ！", "よくやった、{name}! 各墓地が我らの支配下となれば、敵の魂は途方に暮れ、目的も無くさまようこととなろう。", 0x365e6d1f, 0xd4c28523, 0xa7601704, 0x81601597, 0x8a202126, "....." },
  [7101] = { "塔と掩蔽壕", "敵の塔を手に入れ、Alterac MountainsのCorporal Teeka Bloodsnarlのところへ戻って下さい。", "塔と掩蔽壕は重要な場所であり、我々はそれらすべてを手に入れて確保せねばならない! そのために、敵の支配下にある掩蔽壕を攻撃してもらいたい。\n\nそうするには、Allianceの旗のある掩蔽壕へ入るのだ。中に別の旗があるはずだ。その旗を引き抜くと、白いHordeの旗が現れる。うまくやるのだぞ!\n\nその時点で任務は完了だが、もしもそこを一定期間確保することができ、Allianceが奪い返せなければ、そこは破壊される!", "まだ掩蔽壕を襲撃していないな、{name}！ 他の者がお前の栄光を奪うのを待っているのか？", "任務が成功したと聞いたぞ! 喜ばしいことだ……。\n\nこれで我が軍は無事に前へ突き進むことができ、Alterac ValleyにAllianceの場所などないということを示したのだ!", 0xfe4de82e, 0x1a2354d0, 0xf14c6692, 0x80a3e6d5, 0x1ed25e52, "....." },
  [7102] = { "塔と掩蔽壕", "敵の塔か掩蔽壕の軍旗を破壊し、Alterac MountainsのSergeant Durgen Stormpikeのもとへ戻って下さい。", "塔と掩蔽壕は防衛の要で、できる限り多くを確保しなければならん! 君に、Alterac Valleyの塔か掩蔽壕を攻撃して欲しいのだ。\n\nそのためには、上にHordeの軍旗を掲げている塔に入らねばならん。内部に別の敵の軍旗もあるだろう。その軍旗を引きずり降ろし、白いAllianceの軍旗を代わりに掲げるのだ。それで一丁上がりだ!\n\nその時点で任務は完了だが、そのエリアを一定時間確保せねばならん。そして、もしHordeが奪い返せなければ、破壊と相成るわけだ!", "まだ塔を襲撃していないな、{name}！ 何を待っている？", "お前が敵軍旗の確保に貢献したという現地報告を受け取った。よくやったぞ、{name}! 奴らの遠隔部隊が持ち場を離れれば、我々は戦線を前へ移すことができる!", 0xfe4de82e, 0x881b36ad, 0x7db5ba5f, 0x5db7f738, 0xbff4343f, "....." },
  [7121] = { "補給隊将校", "Stormpike Quartermasterと話して下さい。", "{name}、補給隊将校が新兵を自分のところへ向かわせるようにと下命なさった。Alteracの鉱山に蓄えられた物資を必要としておられるので、恐らくそれを取りに行かせるつもりだと思う。\n\nこの道沿いに行け。西に補給隊将校がおられる。", nil, "新兵に会えてよかったぞ、{name}。が、ちょっとした幸運でお前は作戦に参加し、すぐ新入りでは無くなるのだよ!\n\nもう一度話しかけてくれ。お前に話さなければならぬ任務があるのだ……。", 0x9297b1d8, 0x5b898a2d, 0x2651f8ba, nil, 0x22790563, "...m." },
  [7122] = { "鉱山を確保せよ", "Stormpikeが管理していない鉱山を確保し、Alterac MountainsのSergeant Durgen Stormpikeのもとへ戻って下さい。", "Alterac Valleyにある鉱山は、単に鉱物だけを蓄えているだけじゃない。FrostwolfとStormpike双方の余った補給品がIrondeepとColdtooth鉱山に隠してあるんだ... 我々だけがそれらの鉱山を管理下に置くというのは、そう悪い考えじゃないだろう!\n\n鉱山を確保し、私のもとへ戻るのだ。鉱山を確保するためには、我々が管理していない鉱山の一つに入り、そこのリーダーを殺すのだ。君がそれをやってくれれば、鉱山は我らのものになり、その防衛のために兵士を送り込もう!", "まだ鉱山を制圧していないな、{name}！\n\n鉱山を押さえれば、そこから鉱石や物資を集めるのがずっと楽になるのだ。", "やったな! よくやった、{name}!\n\n鉱山を支配しそこに部隊を駐留させれば、鉱物や物資を集めるのがもっと簡単になる。", 0x3ee7a5e5, 0x6d34d083, 0xded25628, 0x0830eb62, 0x62b3948e, "....." },
  [7123] = { "補給隊将校との対話", "Frostwolf Quartermasterと話して下さい。", "{name}、Alterac Valleyの鉱山に入る任務を担う新入りをFrostwolf Quartermasterが求めている。彼と話してくれ。詳しいことを教えてくれるだろう。\n\nこの道沿いを西に進んで掩蔽壕へ行き、西出口から出れば補給隊将校がいるだろう。", nil, "よくきた、{name}! Hordeのために己の役割を果たすことを希望する、お前のような{class}に会えてよかった。再度話しかけてくれ、重要な任務があるのだ……。", 0x7103eddb, 0xf96af497, 0x2e72736a, nil, 0x7f986c13, "...m.", nil, nil, nil, nil, 0x306868db },
  [7124] = { "鉱山を手に入れろ", "鉱山を手に入れ、Alterac MountainsのCorporal Teeka Bloodsnarlのところへ戻って下さい。", "Alterac Valley一帯に戦火が広がったように、Coldtooth鉱山とIrondeep鉱山も戦火が猛威を振るうことになる。ふたつの鉱山は豊富な鉱物資源と物資の貯蔵に使われているのでな、あそこに高い価値があるのは間違いない!\n\n我々の戦勝を支えるのだ、{name}! Hordeのために鉱山のひとつを手に入れよ! 鉱山を手に入れるには、我々が支配していない鉱山の中へ入り、そこのリーダーを殺すのだ。それが終われば、その鉱山は我々のものとなる。我々はそこを守る部隊を派遣しよう!", "まだ鉱山を制圧していないな、{name}！ 我々が押さえていない鉱山を見つけ、その頭目を倒せ！", "鉱山を手に入れたか! 自軍の戦士で守ることで、奥から鉱物を取り出してきたり、ここに蓄えられていた物資を集めてくるのがもっと簡単になるだろう。\n\nよくやった、{name}。お前の行いは、我々が戦いに勝利する上で大いに役立つ。", 0x3ee7a5e5, 0x4079d0e8, 0x09ff1a23, 0x524d28bc, 0xf7493bdd, "....." },
  [7141] = { "Alteracでの戦闘", "Alterac Valleyに入り、Hordeの将軍Drek'tharを討ち、Alterac MountainsにいるProspector Stonehewerのもとに戻って下さい。", "Explorers' Leagueは、Alterac Valleyにアイテムがあると信じているのですが、Frostwolfオーク達が探索をさせてくれないのです。私たちは、Hordeが私たちの学術的探求を止めるのを許してはおけません! Frostwolfの将軍Drek'Tharを討ってください。彼が死ねば、オークたちも士気がくじかれることでしょう。\n\nDrek'TharはAlterac Valleyの南、Frostwolf Keepの中にいます。彼を打ち負かし、私のところに戻って下さい。", "行け、{name}。Alterac Valleyへ行き、オークの将軍を倒すのだ！", "よくやりましたね、{name}! 将軍の死によってHordeの面目が潰れたことで、探索に必要な時間的余裕が手に入りましたよ!", 0xfad36f94, 0xed62d3d9, 0xf217086f, 0xbb5127ce, 0x5e1fca36, "....." },
  [7142] = { "Alteracをかけた戦い", "Alterac Valleyに入り、ドワーフの将軍Vanndar Stormpikeを倒して下さい。その後、Alterac MountainsのVoggah Deathgripのところへ戻って下さい。", "Stormpikeのドワーフと仲間どもがAlterac Valleyを侵略しているので、追い払わねばならん! Alteracをかけた戦いに勝つには、奴らの将軍Vanndar Stormpikeを倒さねばならない!\n\nAlterac Valleyの北にある、Dun BaldarにVanndarがいるはずだ。\n\n奴を討ち滅ぼすのだ、{name}。そして私のところへ戻ってこい。", "我らの故郷にドワーフどもを居座らせはせん！ 敵に襲いかかり、その指導者general Stormpikeを倒せ！", "よくやった、{name}! Stormpikeどもの馬鹿げた侵略に望みはない。\n\nハハハ! 今のところ、奴らがやったことといえば、将軍を殺されたことだけだ!", 0x7151ae32, 0x226f738f, 0xe28e0e37, 0x15e3437d, 0x2a78fe49, "....." },
  [7161] = { "陣地の証", "Alterac Valleyの本拠地南東に位置するWildpaw cavernへ行き、Frostwolf Bannerを見つけて、Warmaster Laggrondのところへ持ち帰って下さい。", "よくきた、{class}。戦いの召集に応じてからだいぶ経った。懐かしい感覚を呼び起こすのは時間がかかるが、一度目覚めてしまえば、戦いの血がたぎる。戦いの激情が戻ってくる……。\n\n谷に来たすべての新人は、初めに戦いの儀式を終えねばならぬ。\n\nWildpaw gnollの洞窟の奥深くにFrostwolfの旗がある。危険を乗り越えて前進し、旗を取り戻せ。私のところへ旗を持ち帰ったら、Frostwolfの新人用バッジを与えよう。", "起きろ！ 起きるんだ、{name}！ これは夢じゃない。お前は本当に、荒れ狂う戦いのただ中に踏みとどまっているんだ！", "お前が感じた燃えるような感覚が、魂を呼び覚ましたのだ。精神が軍への召集を受け入れたのだ。\n\nもうお前はFrostwolfの一員だ、{name}。おめでとう。\n\n常にこのバッジを身につけろ。Frostwolf内での階級が上がるに従い、別のもっと強力なバッジに取り替えてやろう。\n\nいつの日かお前はFrostwolf Clanで高い地位につくだろう。その日が来たら、Eye of Commandが与えられるだろう。", 0x04d66e20, 0x28b91a77, 0x2c393304, 0xa9b6cff9, 0x79b63c2d, "....." },
  [7162] = { "陣地の証", "Alterac ValleyのDun Baldarの南西に位置するIcewing Cavernsに行き、Stormpike Bannerを奪還して下さい。Alterac MountainsにいるLieutenant HaggerdinにStormpike Bannerを持ち帰って下さい。", "ちょうどいいタイミングで来たな、{class}よ。あいつらFrostwolfの野蛮人共はあきらめようとせん! Stormpikeの力を見せつけねばならん。優位に立つ我らに、奴らは屈服すべきなのだ。\n\n戦場に向かう前に、お前、Stormpikeの仲間に入りたいだろう。\n\nDun Baldarの南西に、Icewing Cavernsがある。洞窟の奥深くに置いてあるのがStormpike Bannerだ。危険を顧みずに前進し、あの軍旗を取り戻すのだ。それを私のところに持ち帰れば、Stormpikeの新人用バッジを与えよう。", "この地のharpiesに気をつけろ、{class}。奴らはためらいもなくお前の喉笛を引き裂くぞ！", "{name}、誇りをもってこのバッジを受け取り、身につけるのだ。Stormpike内での階級が上がるにつれ、バッジも変わっていく。Stormpikeの称賛を得たら私のところへ戻れ。お前のバッジを、別のもっと強力なバッジに取り替えてやろう。\n\nいつの日か、お前はこの戦場の伝説の戦士となる。その日が来たら、Eye of Commandが与えられるだろう。", 0x04d66e20, 0xc4061330, 0x0ec79653, 0x04014edf, 0x21a33717, "....." },
  [7163] = { "立ち上がり認められよ", nil, nil, "<Warmaster Laggrondがあなたに敬礼する。>\n\nお前の時が来たぞ、{name}。お前はFrostwolf Clanのために多くを成し遂げ、それによってFrostwolfの兵士としてだけでなく、友としての地位も勝ち取った。\n\n見事だ！ 見習いの記章を見せてみろ。", "新しいこの記章は Frostwolf での地位を表すものだ。肌身離さず持っていろ。\n\nそして{class}よ……栄光のうちに死ね!", 0xf6a70096, nil, nil, 0xf180292a, 0xb16f59f2, ".mm.." },
  [7164] = { "氏族からの称賛", nil, nil, "また会えて嬉しいぞ、{class}。お前が戻ってくるとは思っていなかった。だが、お前はFrostwolfの勇敢で名誉ある兵士であることを証明した。\n\n再びお前の時が来たぞ、{name}。お前は新たな階級を勝ち取った。それにふさわしく、その地位の向上を示す新たな記章を授けよう。\n\n記章を見せてみろ。", "<Warmaster Laggrondは敬礼した。>\n\n行け、{name}! 引き続きFrostwolfを守れ。この戦いは必ず勝たねばならん! Drek'Thar将軍のために! Warchiefのために!", 0x47970b10, nil, nil, 0x9a6b061c, 0x88edba81, ".mm.." },
  [7165] = { "敬意の獲得", nil, nil, "これほど多くが討たれた。血が戦場を染めている。だが……お前は生きている……耐え抜いたのだ。お前は我らの軍を幾度もの勝利へと導いた。ゆえに兵士よ、お前は新たな階級を勝ち取ったのだ。\n\n記章を見せてみろ。", "<Warmaster Laggrond は雄叫びを上げた。>\n\n奴らはもうお前の噂話を始めているぞ、兵士よ。Stormpike一族はお前の名を口にして恐怖に震えている。戦い続けろ!", 0x5151253a, nil, nil, 0x47380b2f, 0x1981d18b, ".mm.." },
  [7166] = { "伝説の英雄", nil, nil, "お前からは統率力と力がみなぎっているぞ、{class}。Frostwolfの目には崇敬すべき者と映り、敵はお前の名を聞くだけで怯えている。\n\n立て、Frostwolfの英雄よ。立ち上がり、栄誉を受けるがいい！\n\n記章を見せてみろ。", "もうすぐ、戦場の者たちは皆お前の注意深い目に見詰められることとなろう。谷の指揮と軍はお前のものとなるのだ!", 0x183f4102, nil, nil, 0x51a77e3b, 0xcebe3776, ".mm.." },
  [7167] = { "The Eye of Command", nil, nil, "Drek'Tharがお前を褒め称えている。Kalimdorはお前の英雄譚で持ちきりだ。大族長も上機嫌だ。お前が我らの氏族を揺るぎなく守り抜いたことを、大いに喜んでおられる。\n\nお前はEye of Commandを手にするにふさわしい。\n\n記章を見せてみろ、Commander {name}。", "記章の力と一体となるのだ。敵に声を聞かせてやれ。Horde の力は確かなものだ!", 0x4cd4f1de, nil, nil, 0xcc2b7cbc, 0x2879f838, ".mm.." },
  [7168] = { "立ち上がり認められよ", nil, nil, "たいていの者は、己の凡庸さを超えるまで生き延びることができない。お前は模範的な兵士であることを証明したぞ、{class}。時は来た。\n\n記章を見せてみろ。", "我が軍の兵士が敵を倒したのだと示してやれ! Stormpike の栄光のために戦え!", 0xf6a70096, nil, nil, 0x259975b2, 0xc0c34438, ".mm.." },
  [7169] = { "衛兵からの称賛", nil, nil, "Field of Strifeでのお前の活躍の知らせで、基地は持ちきりだ！ お前は敵に強烈な打撃を与え、その士気を打ち砕いた！ この功により、お前はStormpikeにおける名誉ある階級を勝ち取ったのだ。\n\n記章を見せてくれ。", "{class}、王は前線でのお前の英雄的功績をご存じである。引き続きStormpike Guardをしっかりと守れ!", 0xe9b6400b, nil, nil, 0x17f2f423, 0xf8145b52, ".mm.." },
  [7170] = { "敬意の獲得", nil, nil, "どうしても知りたいのだ、{name}。敵の目をまっすぐ見据えたとき、そこに恐怖は見えるか？ 奴らは今や、お前の前で怯えているか？ 奴らは自分たちが負けたと思い知るべきだ！\n\nお前は衛兵の間で敬意を勝ち取った。記章を見せてくれ！", "初めてお前と会った時、一人の英雄が形作られつつあるとは思いもしなかった。頑張れ、兵士よ!", 0x5151253a, nil, nil, 0x55b1b3b3, 0x49a6b49c, ".mm.." },
  [7171] = { "伝説の英雄", nil, nil, "私の前に立っているのは、Allianceの崇敬すべき英雄だ。\n\n<Lieutenant Haggerdinが敬礼する。>\n\nStormpikeでこれほどの階級を得た者はほとんどいない。私はお前の前に敵が倒れていくのを見てきた。お前を前にして奴らの決意が崩れ去るのを見てきた。お前が戦いに加われば、我が軍にとっての希望の光となるのだ！\n\n記章を見せてくれ。", "間違いなくお前はEye of Commandを持つ者となる!", 0x183f4102, nil, nil, 0x2e17a93c, 0x01ec6f86, ".mm.." },
  [7172] = { "The Eye of Command", nil, nil, "奴らにお前の声を聞かせてやれ、Commander {name}！ 恐怖を思い知らせるのだ。Stormpikeの隊列にどれほどの力があるかを見せつけてやれ！\n\n記章を見せてくれ。", "我が軍を勝利へ導くのはお前だ、指揮官! 兵士はお前の指揮下にある。皆、命令に従うだろう。兵士を率いて……Frostwolf を打ち破れ。", 0x4cd4f1de, nil, nil, 0xeffb93ec, 0xc004124f, ".mm.." },
  [7181] = { "Korrakの伝説", "伝説によれば、強大なWinteraxのトロールの長は、意のままに現れてAlterac Valleyの住人たちに災いをもたらすという。\n\nKorrakが姿を現したら、彼を倒してWarmaster Laggrondのところへ戻って下さい。", "この地域の脅威は、侵攻してくるStormpikeだけではないぞ、兵士よ。Valleyでの戦いは二つの戦線で行われている。人食いのWinteraxトロールもまた、覇権を争っているのだ。\n\n奴らを率いるのはKorrak the Bloodrager――残忍で狡猾な獣だ。\n\nKorrakを討てば、Winterax族に壊滅的な打撃を与えられるかもしれん。その獣を倒せ。褒美を取らせよう！", nil, nil, 0xed7de448, 0xd4561934, 0xff819931, nil, nil, "...mm" },
  [7201] = { "最後の元素", "Blackrock Depthsへ行き、Essence of the Element 10個を取り戻して下さい。まず最初に行うのは、ゴーレムとその製作者を探すことです。また、Vivian Lagraveは精霊のことを何か呟いていました。", "深部へ踏み込む者には仕事があるぞ、{name}。\n\nDark Ironsは、極めて強力なゴーレムの製造を極めた。\n\n我々の密偵からの最初の報告によれば、ドワーフどもは独自の動力源を使い、その創造物に比類なき殺傷力を与えているらしい。\n\nこのessence of the elementsを手に入れられたら、我々のabominationsで何ができるか想像してみろ! 必要なら都をひっくり返してでも、essenceを見つけるまで戻ってくるな! 報酬は危険に見合うものになるぞ。", "私に見せてみろ！", "素晴らしい! これはただちに使者でUndercityへ送らせよう!\n\nお前にはな――約束どおり、ここに支払いがある。釣りは取っておけ、この薄汚い獣め!", 0x19b2e88f, 0xfd70e576, 0xf6bdad3c, 0xeae5b052, 0x635624c4, "....." },
  [7202] = { "Korrak the Bloodrager", "伝説によれば、強大なWinteraxのトロールの長は、意のままに現れてAlterac Valleyの住人たちに災いをもたらすという。\n\nKorrakが姿を現したら、彼を倒してAlterac MountainsのLieutenant Haggerdinのところへ戻って下さい。", "この地域に古くから住むWinteraxトロールは冷酷な野蛮人で、我々の骨を奴らの汚らわしいシチューに加えることを何よりも望んでいる。\n\n我々の力を見せつけてやらねば！\n\n奴らの洞窟から、指導者の序列を詳しく記した書物を取り戻した。その品々によれば、奴らの指導者Korrak the Bloodragerは、姿を現す理由ができるまで身を潜めていることが多いらしい。\n\nKorrakの死はWinterax Clanの死を意味する！奴を倒して戻ってこい。", nil, nil, 0x7f5c48d4, 0xe603d27a, 0x8a04047a, nil, nil, "...mm" },
  [7221] = { "Prospector Stonehewerと話す", "Dun Baldarの駐屯地にいるProspector Stonehewerと話して下さい。", "おお、{name}、任務に就きに来たのか？よし、Stormpikesは集められる者なら誰でも必要としてるんだ！\n\nDun BaldarのProspector Stonehewerと話してくれ。敵地への重要な任務のために人を集めてる。StonehewerはDun Baldarの駐屯地の一番下にいるぞ。\n\nそれから、Dun Baldarを通る時はよく目を配っておけ。手を汚すのを恐れない働き者の{class}にとっちゃ、やることは山ほどあるからな。", nil, nil, 0x98c2799b, 0x0a68d03c, 0x33ca6bdc, nil, nil, "...mm", nil, nil, 0x88b33eac, nil, nil },
  [7222] = { "Voggah Deathgripと話す", "Frostwolf KeepのVoggahと話して下さい。", "{class}か？よし！Alteracへよく来た、{name}。侵入者のドワーフどもとその仲間が我らの谷を侵している。Hordeの者なら誰でも、この正義の殺戮に加わることを歓迎するぞ！\n\nVoggah Deathgripと話せ。Alterac ValleyにあるAllianceの拠点への重要な任務のために、手先を探している！\n\nVoggahはFrostwolf Keepにいる。", nil, nil, 0xc1f1cfcf, 0xb95ee89f, 0xed8789bc, nil, nil, "...mm" },
  [7223] = { "Armor Scraps", "Armor Scraps 20個をDun BaldarのMurgot Deepforgeに渡して下さい。", "Alterac Valleyの戦いは絶え間なく激しさを増し、Ironforgeから来る物資は歴戦の戦士たちの防具一式を揃えるには足りない。\n\n戦場で防具のがらくたを見つけたら、戦勝を支えるために、がらくたを持ってきてくれ!", "armor scrapsは持ってきたか、{name}？", "これはまあまあ良い部品だな、{name}。兵士たちの新しい装備を作るためにはこれが必要なんだ。\n\nわしの供給レベルが充分高くなれば、熟練の戦闘部隊が戦場へ赴くことができるだろう!", 0x69379f11, 0x1807f1cc, 0x38242264, 0x59127735, 0xc2035332, "....." },
  [7224] = { "略奪品", "Frostwolf VillageのSmith RegzarにArmor Scraps 20個を渡して下さい。", "敵と戦ったら、そいつらの防具のがらくたを集めて俺のとこへ持ってきてくれ。我が軍のための防具を作るのに使うんだ!", "狩りの調子はどうだ、{name}。armor scrapsは手に入ったか？", "これは良さそうだ。これを溶かして繋ぎ合わせれば、これがStormpikeの臆病者めらのものだなんて分からなくなるぜ!\n\nありがとよ、{name}。それとあんたの防具を磨かせてくれ……", 0x665bfb65, 0x8eea36b9, 0xd25d0295, 0xee41626a, 0xea2bbb5f, "....." },
  [7241] = { "Frostwolfを守るために", "Alterac Mountainsに位置するAlterac Valleyへ向かって下さい。Warmaster Laggrondを見つけ、Frostwolfの兵士としての一歩を踏み出すために彼と話して下さい。彼はトンネル入口の外に立っています。Alterac Mountainsの麓にあるTarren Millの北にAlterac Valleyがあります。", "遠い地で戦の太鼓が鳴り響いている、{class}。お前の大族長が目をかける氏族が、IronforgeのあくどいStormpike Guardに攻撃されているのだ。\n\n見たところ、お前は確かに戦い慣れており、Frostwolfの大義を担う覚悟ができているようだな。\n\n今こそお前が、己の成長の次の一歩を踏み出す時だ。\n\nTarren Millの北、AlteracにAlterac Valleyへの入口がある。そこでWarmaster Laggrondに会え。急げ、{class}。戦いは目前だ！", nil, "Frostwolfの兵士となるには、初めに試さねばならぬことがある……", 0xfae48c83, 0x66ddcb30, 0x720a3a61, nil, 0x668caba0, "...m." },
  [7261] = { "最高責務", "Hillsbrad FoothillsのAlterac Valleyへ行く。入口のトンネルの外でLieutenant Haggerdinを見つけて話して下さい。\n\nBronzebeardの栄光のために!", "我々はAlteracの谷で熾烈な戦いを繰り広げている。人食いのWinteraxのトロールどもが一方から、野蛮なFrostwolf Clanがもう一方から襲いかかってくるのだ。どちらもKing Magni Bronzebeardの名のもとに殲滅せねばならん！あの地を奪い、敵を間引き、塗り替えることは、Ironforge王国にとって主権と領土に関わる至上命題なのだ。\n\nだが残念ながら、兵士は木に生えてはこない！Alterac Valleyの外にいるLieutenant Haggerdinに報告し、Stormpikeの一員として任務と名誉の軍務を始めてくれ。", nil, "仕事に取り掛かろうか!", 0xb7b70a8b, 0x5fa8b95f, 0x252df73c, nil, 0x11d89b67, "...m." },
  [7281] = { "兄弟愛", "Stormpikeの領土に入り、Commander Karl Philipsを倒す。任務を終えたらCommander Louis Philipsのところへ戻って下さい。", "悲劇だ……私の兄弟が戦場で私と相対している。Stormpikeの司令官としてな。\n\n四人のStormpike Commandersのうち、奴は間違いなく最も危険だ。奴を討てば、Banshee Queenが私にしたように奴を変えてくださるかもしれん――奴に過ちを悟らせてくださるかもしれん……\n\n敵地の奥深くに私の兄弟がいる。奴を倒して私のもとへ戻れ。お前ならこの任務を果たせると信じているぞ、兵士よ。\n\nそれから兵士よ、一人で行くな。", "愛する兄弟が完全なる存在へと昇華したというのに、自分は生者の一人として留まらねばならぬとは、彼にとってさぞ苦痛であろうな。", "君の英雄的な働きは見過ごされはしない、{name}。\n\n彼を救うなら一刻の猶予もない。Sylvanasに知らせねば!", 0xe7d8245f, 0x343b6536, 0x71625dbe, 0x9676ad25, 0x5d8df78e, "....." },
  [7282] = { "兄弟愛", "Frostwolfの領土に入り、Commander Louis Philipsを倒す。任務を終えたらCommander Karl Philipsのところへ戻って下さい。", "奴を苦しみから解放してやらねばならん、兵士よ！奴は自分が何をしているのか分かっていないのだ。恐るべきBanshee Queenの心なき下僕に成り果ててしまった。\n\nField of Strifeを越え、Frostwolfの領地の奥深くへ進め。私の兄弟を見つけ、滅ぼしてくれ。奴の苦しみに終止符を打たねばならん。", "このような命令を下すのは心苦しいのだ、兵士よ。", "死体を焼くのは忘れなかっただろうな?", 0xe7d8245f, 0x64276aa1, 0xc6b30ac3, 0x476a1a98, 0xaae31659, "....." },
  [7301] = { "堕ちた空の王たち", "Frostwolfの領土へ行き、Wing Commander Slidore、Wing Commander Vipore、Wing Commander Ichmanを探す。任務を果たしたらCommander Duffyのところへ戻って下さい。", "奴らのWing Commandersは捕虜にしてある、{race}。大空での激しい戦いだったが、ついに奴らは墜ちた！だが残念なことに、うちの最高のパイロットたちがFrostwolf Keepへの反撃で撃ち落とされてしまった。彼らに何があったのか突き止めてくれ。\n\nTower Point WestとFrostwolf Keepを捜索しろ。そこが彼らの最後に確認された場所だ。その一帯を徹底的に探してくれ。", "何か私が聞きたくなるような話はあるか？", "信じられない! ちゃんと解放したんだよな? そうだよな??? まあ、少なくとも彼らがどこに捕らえられていたかは分かった。", 0x6d34555a, 0xf46c68a4, 0x9ce6f09e, 0x5aab64b2, 0xe9d4b48e, "....." },
  [7302] = { "堕ちた空の王たち", "Wing Commander Guse、Wing Commander Jeztor、Wing Commander Mulverickがどうなったかを突き止める。任務を果たしたらCommander Mulfortのところへ戻って下さい。", "我らの航空支援はめちゃくちゃだ、{name}。Wing Commandersが敵地の上空で撃ち落とされた。救出を試みられるよう、彼らがどうなったのか突き止めてくれ！\n\nGuseが最後に目撃されたのはIcewing Bunkerの上空を飛んでいた時だ。Jeztor's War RiderはStormpikeの製材所の近くで見かけられた。Mulverickは……あの無鉄砲な馬鹿は、Dun'Baldar North Bunkerの近くに墜落するのを見られている。\n\n俺が持っている情報はそれだけだ。行け！その一帯を徹底的に探せ。", "狩りの状況はどうだ、兵士？", "よくやった! 君が取り戻した情報は、我々の大義にとって計り知れない価値がある。", 0x6d34555a, 0x0c7e950b, 0xeadb4a89, 0xf4f7d78d, 0xaacc5616, "....." },
  [7321] = { "Soothing Turtle Bisque", "Tarren MillのChristoph JeffcoatにTurtle Meat 10ピースとSoothing Spicesを渡して下さい。", "アンデッドは料理のことなんか何も分からないって、誰が言ったんだい？例えば俺の秘伝のTurtle Bisqueを見てみなよ。一杯味わうためだけに死の淵から戻ってきた連中だって知ってるんだぜ！へっへっ……\n\nそういえば、ここのところずっと作れてないんだ。前は自分でLake Lordamereまで行ってsnapjawsを狩ってたんだが、あのいやな奴らをな。今はここの仕事から手が離せなくてね。\n\nsnapjawsのTurtle Meatとsoothing spicesを持ってきてくれたら、作り方を見せてやるよ！", "材料は見つかったか？ 言っておくが、今このあたりにはallianceのウジ虫どもが多すぎる……私に言わせれば、奴らはもうすでに近づきすぎているのだ……", "俺のsoothing turtle bisqueは、寒い夜でも体をぽかぽかにしてくれるぜ……その手のことに関心があるならな。", 0xc8acfcb2, 0x5b979eb8, 0xb1398037, 0x0b383a67, 0x5b8e08bd, "....." },
  [7361] = { "Darkspearの信頼", "Alterac Valleyで敵対するナイトエルフのプレイヤーを倒す任務を与えられた。\n\nナイトエルフを倒し、Severed Night Elf Headを持ってFrostwolf KeepのNajak Hexxenのところへ戻って下さい。", "<Najakがうなり声をあげる。>\n\nナイトエルフが生まれる前、トロールがいた。ナイトエルフはトロールから生まれたのだ。\n\n我が民への奴らの反逆的な攻撃は許さん。Staghelmは我らを根絶やしにしようとしている――奴とその同類を生み出した者たちの痕跡を何一つ残さぬようにな。そうはさせん！\n\nナイトエルフを一人倒して首をはねるたびに、NajakがDarkspearの中でお前の名を高めてやろう。お前の行いの噂はKalimdorとEastern Kingdomsの隅々にまで広まるだろう。さあ行け、Darkspearに仕えるのだ！", "奴らは我々を根絶やしにするつもりか？ 根絶やしにされるのは奴らの方だ。", "{name}、これは数千のうちの1つにすぎん。だが、よくやった。", 0xbb842c90, 0x55dbcc07, 0x51444619, 0xc293408d, 0x749c39af, "....." },
  [7362] = { "トーレンの盟友", "Alterac Valleyで敵対するノームのプレイヤーを倒す任務を与えられた。\n\nノームを倒し、Tuft of Gnome Hairを持ってFrostwolf KeepのRavak Grimtotemのところへ戻って下さい。", "Elder Croneは、他の種族を調べるために私をこの戦場へ送った。より具体的には、ノームの標本を集めることになっている。Magathaが主に関心を持っているのは、奴らのしぶとさだ。そうとも、ノームは――哀れなほど弱く小さいが――戦いの内でも外でも大いなる回復力を見せる。\n\nお前にとっては幸いなことに、私はMagathaの命を果たしてくれる荒くれ者を探している。ノームの毛の房を持って戻れば、お前はトーレンの味方として知られることになろう。", "髪がどこから取れたものかなど、どうでもいい、{race}。", "ああ、こいつは間違いなくノームのものだ。よくやった、{race}。だが、まだやるべき仕事はあるぞ。", 0x65d13387, 0xddab1d4c, 0x42538f61, 0x4ba8f1be, 0x1e4f0d2b, "....." },
  [7363] = { "人間の条件", "Alterac Valleyで敵対する人間のプレイヤーを倒す任務を与えられた。\n\n人間を倒し、Human Bone Chipを持ってCommander Louis Philips(前線とFrostwolf keepの間をうろついている)のところへ戻って下さい。\n\n人間という病の治療法はもうすぐ手に入る！", "人間というのは、まったくもって忌まわしい。\n\n<Commander Philipsが顔をしかめる。>\n\n確かに私はFrostwolfの兵士だが、今もSylvanasの僕であることに変わりはない。\n\n任務の合間に、UndercityのDark Apothecariesのために副業をしている。\n\n人間という病を治すのに使う、人間の骨片を集める任務を与えられているのだ。\n\nその任務を部下に回すことも許されている。\n\n奴らを見つけろ。殺せ。奴らの骨片を私のもとへ持ってこい。", "ああ、本当だ。私の兄弟は人間だ。恥ずべきことだ……ほぼ汚点のない私の経歴についた染みだよ。", "奴らが自分の病を受け入れて、お前の癒しの手に身を任せてくれれば楽なんだがな。まあ、それじゃあ面白みも減るだろうが。続けろ! どうにかして、奴らを治してやるさ。", 0xd69d3463, 0x7cca400f, 0xea160936, 0x27c2c300, 0x563eb6c3, "....." },
  [7364] = { "Gnomereganの懸賞金", "Alterac Valleyで敵対するトーレンのプレイヤーを倒す任務を与えられた。\n\nトーレンを倒し、Tauren Hoofを持ってDun'BaldarのDirk Swindleのところへ戻って下さい。", "High Tinkerer自らが、ノームの兄弟姉妹を守るために私をこの戦場へ送り込んだんだ。トーレンがノームを狙い撃ちにして殺しているという知らせが届いている。何より最悪なのは、奴らが倒れた者の亡骸から、輝かしいノームの髪の房を刈り取っていることだ。こんな残虐行為はやめさせなきゃならない。やり返すんだ！\n\n奴らの蹄を剥ぎ取ってやれ、{class}。蹄を持ってきてくれ！ノームの味方だってことを示すんだ。", "奴らを足を引きずるようにしてやれ、{name}。ノームの民がいじめられて黙っていないことを思い知らせなきゃならん！", "*Dirkはhoofを背後の山に放り投げた。*", 0x10be540e, 0xa4846809, 0xfb9be150, 0xaa25b738, 0xa1a51d0a, "....." },
  [7365] = { "Staghelmの鎮魂歌", "Alterac Valleyで敵対するトロールのプレイヤーを倒す任務を与えられた。\n\nトロールを倒し、Darkspear Troll Mojoを持ってDun'BaldarのAthramanisのところへ戻って下さい。", "Staghelmが命令を下した。戦場のトロールはすべて根絶やしにせねばならない。ナイトエルフを生み出したなどという奴らのばかげた主張には、力と然るべき偏見をもって応じねばならない。\n\n奴らを倒し、奴らのmojoを持って私のもとへ戻れ。繰り返す。奴らのmojoを盗んでこいと言っているのだ。", "臭いトロールどもの匂いがまだ鼻につく。", "ありがとう、{name}。空気が少し清らかになった。", 0x08cdaa41, 0xe58b9166, 0x2adc4321, 0x7dc3e477, 0x3fcbf2b4, "....." },
  [7366] = { "大司教の慈悲", "Alterac Valleyで敵対するForsakenのプレイヤーを倒す任務を与えられた。\n\nForsakenを倒し、Forsaken Heartを持ってCommander Karl Philips(製材所と鉱山の間をうろついている)のところへ戻って下さい。", "大司教は賢明であると同時に慈悲深いお方だ。あのような惨めな連中に、人が慈悲の目を向けるとは……\n\n<Commander Philipsが信じられないというように首を振る。>\n\n慈悲深すぎる……あまりにも慈悲深すぎる。\n\n大司教は、アンデッドを哀れみ、速やかで永久の死を与えてやるよう求めておられる。この慈悲の盛大な表明のために、我々は奴らの黒く病に冒された心臓を頂戴するだけでいい。\n\nForsakenの心臓を持ってこい。Cathedral of Lightで厳かに焼き尽くすのだ。急げ、{name}！", "Benedictus！ 私など、あのお方の偉大さの影にある塵に過ぎません。あのお方を讃えよ！", "Benedictusを称えよ! またひとつ迷える魂が、光の白熱の炎によって救われるのだ!\n\n行け、おお光の兵士よ! さらに多くを救わねばならぬ!", 0xe121e255, 0x175b2ded, 0x9ca82885, 0xb55cdc18, 0x1852056e, "....." },
  [7367] = { "脅威の解除", "Frostwolf Explosives Expertを見つけて倒す。任務を終えたらStormpike Explosives Expertのところへ戻って下さい。", "Frostwolfは前線と基地に罠を仕掛けているぞ、{class}。敵地へ攻め込む時は足元に気をつけなきゃならない。\n\n奴らに確かな一撃を加えたいなら、対人兵器の供給源を潰すんだ――奴らの爆発物の専門家のことだ。そいつを倒せば、地雷を安全に解除できる。そいつを倒したままにしておけば、地雷も解除されたままになる。\n\nたぶんIceblood Garrisonの近くの塔にいるはずだ。幸運を祈る！", nil, nil, 0x76f2dd62, 0x23693407, 0xd11d881e, nil, nil, "...mm" },
  [7368] = { "脅威の解除", "Stormpike Explosives Expertを見つけて倒す。任務を終えたらFrostwolf Explosives Expertのところへ戻って下さい。", "地雷のことなら何でも知ってるぜ。なにしろ、ここの前線に地雷を全部仕掛けてるのは俺なんだからな。\n\nStormpikeの地雷原を無力化したいなら、奴らの爆発物の専門家を殺せばいいだけだ。あのドワーフの臆病者は、Field of Strifeの一つ目の塔に隠れてるに違いない。そいつを片付ければ、解除した地雷が元に戻ることはなくなる。\n\nもし奴を殺せたら、ここへ戻って知らせてくれ。善行には報いがあるべきだからな。", nil, nil, 0x76f2dd62, 0xdfc6b932, 0x418a5840, nil, nil, "...mm" },
  [7383] = { "大地の冠", "Amethyst Phialに水を汲み、DolanaarのCorithras Moonrageのところへ持ち帰って下さい。", "だがな、Teldrassilもうまく行くことばかりじゃなかった。Staghelmが入念に作った新しい世界樹の計画は思惑通りに進んだものの、ひとつ問題があった。Teldrassilに関するいろんな問題を引き起こしかねない問題がな。\n\nまあ、今はそこまで突っ込むつもりもない。最後のMoonwell、北西のOracle Gladeへ行くのだ。Oracle Treeの下にあるのは最初にして最も力あるMoonwellだ。瓶をその水で満たし、私の元へ届けてくれ。", "ドルイドたちと共に、Oracle Treeと大ドルイドはTeldrassilの成長を注意深く見守ってきました。けれども、新たな故郷を得たとはいえ、私たちの不死の命は戻っていないのです。", "Oracle Treeの前にいると……知恵が形を成すのを感じるかのようです。話の続きをしましょう……\n\nTeldrassilが育つと、大ドルイドはドラゴンたちのもとを訪れ、その祝福を求めました。かつて太古の時代に、ドラゴンたちがNordrassilに祝福を授けたように。しかし、Lord of TimeであるNozdormuは祝福を与えることを拒み、ドルイドの傲慢さをたしなめたのです。Nozdormuに同意して、AlexstraszaもまたStaghelmを拒みました。そして彼女の祝福がないまま、Teldrassilの成長は歪で予測のつかないものとなってしまったのです……", 0x6a9c354f, 0x00e3b1b6, 0xa9b364df, 0xb7686ed0, 0x195e31f7, "....." },
  [7401] = { "指名手配：ドワーフ！", "Alterac Valleyで敵対するドワーフのプレイヤーを倒す任務を与えられた。\n\nドワーフを倒して背骨を引き抜く。Dwarf SpineをFrostwolf KeepのSergeant Yazra Bloodsnarlのところへ持って行って下さい。", "Sergeant Yazra Bloodsnarlの命により、戦場のドワーフはすべて見つけ次第殺すこと。\n\n戦闘でドワーフを倒したら、その背骨を引き抜き、背骨のない悪臭と腐敗の塊を残して、Frostwolfの力に逆らおうとするあらゆる者への警告とせよ。\n\n武勇の証を持ってSergeant Yazra Bloodsnarlのもとへ戻ること。", "私は皮肉を卸売りで扱っているのだ、兵士よ。", "これでドワーフをダース単位で始末する許可が出たぞ、{class}!\n\n<Yazraはしばらく遠くを見つめる。>\n\n初めての背骨抜きは忘れられないものだ……", 0x0c8299d4, 0xc0cbc4eb, 0x534ec6af, 0xf47a1bad, 0xf0ebc0d0, "....." },
  [7402] = { "指名手配：オーク！", "Alterac Valleyで敵対するオークのプレイヤーを倒す任務を与えられた。\n\nオークを倒してOrc Toothを奪い、Dun BaldarのCorporal Noreg Stormpikeのところへ持ち帰って下さい。", "Corporal Noreg Stormpikeの命により、戦えるStormpikeの兵士はすべて、戦場で遭遇した敵のオークを倒すこと。\n\n兵士は敵の口から牙または歯を抜き取り、その歯を手柄の証として提出すること。\n\n保護手袋を着用のこと。", "歯を引っこ抜くのにペンチでも要るのか？", "よし、{name}。あのちっぽけなネズミどもも待っているぞ。", 0xb38692af, 0x57619e21, 0x9dce9870, 0xefeadcea, 0xa31eaed3, "....." },
  [7441] = { "PusillinとElder Azj'Tordin", "Dire Maulへ行き、ImpのPusillinを見つける。どんな手を使ってもいいので、PusillinにAzj'TordinのBook of Incantationsを渡させて下さい。\n\nBook of Incantationsを取り戻したら、FeralasのLariss PavilionにいるAzj'Tordinのところへ戻って下さい。", "ほんの一瞬、油断してしまったのだ、見知らぬ者よ。堕ちた王子の手から逃れようと急ぐあまり、盗みに遭った。impのPusillinという実に卑しい悪魔が、私のbook of incantationsと、かつて壮麗であったEldre'Thalasの広間の鍵をかすめ取っていったのだ。\n\n鍵にはもう興味はない。私は不死と引き換えに自由を得たのだから。だが、book of incantationsはどうしても必要なのだ。\n\nimpのPusillinを見つけ、私の本を取り戻してくれ。\n\nDire MaulのWarpwood QuarterでPusillinを探すのだ。", "我は何も悔いてはおらぬ、見知らぬ者よ。女王はとうの昔に亡くなった。Shen'Dralarの業績は、Prince Tortheldrinの狂気によって汚されてしまった。我が求めるのは自由のみ……逃れることだけだ……", "見つけてくれたのか! あの惨めなインプに呪いあれ。ああ……私の持ち物はせいぜいこんな程度だ。お礼にこの中から好きな物を選んでくれ。", 0x059f80f6, 0xe43a7809, 0x19ed981b, 0x94b8d9e2, 0x5062574d, "....." },
  [7461] = { "内なる狂気", "Prison of Immol'tharに力を供給している$N1基のPylonsを囲む守護者たちを倒さなければならない。Pylonsの動力が落ちれば、Immol'tharを囲む力場は消えるだろう。\n\nPrison of Immol'tharに入り、その中心にいる忌まわしい悪魔を滅ぼす。最後に、AthenaeumでPrince Tortheldrinと対決する。\n\nこのクエストを達成したら、中庭にいるShen'dralar Ancientのところへ戻って下さい。", "もう十分に聞いたか？君は行動の人か？\n\nこの狂気は終わらせねばならない。不死の者たちの時代はとうに過ぎ去った。パイロンを囲む守護者たちを倒し、力場を下ろせ。それが済んだらImmol'tharを滅ぼせ。王子の力が大きく削がれたところで、攻めかかって奴に止めを刺すのだ。この都の霊たちを眠らせてやってくれ、冒険者よ。", "用心するのだ、冒険者よ。王子は……人を言いくるめるのが巧みだ。", "感謝致します、英雄よ。", 0x3d8cb4ce, 0x816563e0, 0x29a10d44, 0x4fc25a7c, 0x6a0ceb7f, ".....", nil, nil, 0xca71c4f1, nil, nil },
  [7462] = { "Shen'dralarの財宝", "Athenaeumへ戻り、Treasure of the Shen'dralarを見つける。報酬を受け取って下さい！", "図書館Athenaeumの階段の下に、古い箱が隠されている。そこから望むものを持っていけ。", nil, "箱を開けると、中には……", 0xe29bd883, 0x031a4aa1, 0x4ca8e2d2, nil, 0x549f5efb, "...m." },
  [7463] = { "神秘の水", "Dire MaulのWarpwood Quarterへ行き、水の精霊Hydrospawnを討ち取って下さい。AthenaeumのLorekeeper LydrosのところへHydrospawn Essenceを持ち帰って下さい。", "{race}のメイジだと！なんと素晴らしい。お前の同族を見るのは……ええと、どれくらいになるかな？$N1年ぶりだ！\n\nお前の渇きを癒すものを持っているが、まずは私のために一仕事してもらわねばな。\n\n<Lydrosがくすくすと笑う。>\n\nEldre'Thalasに異変がある。水のエレメンタルが東の翼に居着いたのだ。その存在は記録されねばならん！\n\nWarpwood Quarterへ赴き、Hydrospawnのエレメンタルの精髄を一部抜き取ってこい。それを持ち帰れば、役に立つ小呪文を教えてやろう。", "何だ？ 私はお前を知っていたか？", "素晴らしい! 君は誰だったかな? おお、そんなことはいい。何をあげたらよいだろう? ふーむ……よし、君はメイジだから、恐らくこれが役立つだろう。", 0x66eabbdb, 0x2fdbc927, 0xaf59a200, 0xb6829be6, 0xc75847ce, "....." },
  [7481] = { "エルフの伝説", "Dire MaulでTelmius Dreamseekerを探して下さい。知り得た情報はすべてCamp MojacheのSage Koroluskに報告して下さい。", "数年前、Telmius Dreamseekerという孤高のエルフの師が、いくつかの古代エルフの遺物を携えて、荒廃した故郷から逃れました。\n\nこの失われた師を探す私たちの旅は、Quel'Thalasの廃墟からBurning Steppesを抜け、広大な海を渡り、Feralasへと至りました。\n\n私たちは、そのエルフがEldre'Thalas（今ではDire Maulと呼ばれる場所）の広間に避難したのではないかと考えています。\n\n彼を見つけてください、冒険者よ。生きていようと死んでいようと、彼が携えていた知識は取り戻さねばならないのです！", "私の仲間であるナイトエルフの学者Runethornが、この任務のために同志を集めています。", "残念……無念だ。物は無くなっていたそうだね。彼の痕跡も無かったのだろう?", 0x1f2f44c8, 0x48fcc84f, 0x0c64d56a, 0xd17d6d54, 0x25e7e4f2, "....." },
  [7482] = { "エルフの伝説", "Dire MaulでTelmius Dreamseekerを探して下さい。知り得た情報はすべてFeathermoonのScholar Runethornに報告して下さい。", "数年前、Telmius Dreamseekerという孤高のエルフの師が、いくつかの古代エルフの遺物を携えて、荒廃した故郷から逃れました。\n\nこの失われた師を探す私たちの旅は、Quel'Thalasの廃墟からBurning Steppesを抜け、広大な海を渡り、Feralasへと至りました。\n\n私たちは、そのエルフがEldre'Thalas（今ではDire Maulと呼ばれる場所）の広間に避難したのではないかと考えています。\n\n彼を見つけてください、冒険者よ。生きていようと死んでいようと、彼が携えていた知識は取り戻さねばならないのです！", "私の仲間であるトーレンの賢者Koroluskが、この任務のために同志を集めています。", "残念……無念です。物は無くなっていたそうですね。彼の痕跡も無かったのでしょう?", 0x1f2f44c8, 0xb62937c9, 0x0c64d56a, 0x4a5e2edd, 0x25e7e4f2, "....." },
  [7486] = { "英雄の報酬", "Hydraxis' Cofferから報酬を受け取って下さい。", "{name}、Warlordsへのそなたの奉仕は、この世界の住人に我らが期待し得るすべてを超えていた。\n\n我らには、そなたらの民の感謝や善行への報いという考えが分からぬ。だが、この場合は……報いが与えられてしかるべきかもしれぬ。\n\nこの島の南の麓、波の下に、宝箱がある。その中に、そなたの……報酬がある。\n\n行け、{name}。報酬を受け取るがよい。", nil, "Hydraxisの声が水面から降りてくる……\n\n「そなたに最もふさわしいものを選ぶがよい、{name}。それがWaterlordsの敵からそなたを守らんことを。」", 0x13f3267c, 0x6a5366b3, 0x9e6438a6, nil, 0x2dd65d0e, "...m." },
  [7487] = { "Coreへの同調", "Blackrock DepthsにあるMolten Coreの入口ポータルへ行き、Core Fragmentを回収する。Core Fragmentを回収したら、Blackrock MountainのLothos Riftwakerのところへ戻って下さい。", "裂け目が我らの周りのいたる所で蠢き、裂け、崩れている、{race}。私の立つ場所から二歩と離れぬところに、Blackrock Mountainの深みを抜け、Firelordの顎へと通じる裂け目がある。\n\n驚いたか？哀れなことだ……定命の種族は、見ることも、触れることも、感じることもできぬものを理解できぬ。\n\n請け合おう、ポータルはそこにあり、通ることもできる。\n\n興味が湧いたか？同調は簡単だ。Blackrock Depthsへ行き、core fragmentを取ってこい。それを私のもとへ持ち帰れば、お前の本質をポータルに同調させてやろう。", "今その裂け目に飛び込めば、大惨事になりかねない……お前にとってな。", "我の右手にある入り口をくぐるがよい。さすればMolten Coreの内部に至るであろう。", 0x9b377bde, 0x3bb79f5f, 0x5c97dddf, 0xd4ff6138, 0x5ad762e4, "....." },
  [7488] = { "Lethtendris's Web", "FeralasのFeathermoon StrongholdにいるLatronicus Moonspearに、Lethtendris's Webを渡して下さい。", "メイジのLethtendrisは凶暴なblood elfで、その残忍さに並ぶのは魔法への歪んだ依存だけという女です。彼女がDire Maulへ逃げ込みました。彼女はある装置を作りました。あの地の魔力を絡め取る網です。放っておけば、彼女は私たちの世界に取り返しのつかない害を及ぼすのではないかと恐れています！\n\n彼女を止めてください、{name}。見つけ出して、webを取り戻すのです。おそらくDire MaulのWarpwood Quarterのsatyrsの近くにいるでしょう。その力を安全に自然へ解き放てるよう、webを私のところへ持ってきてください……", "蜘蛛の巣は持っているか、{name}？ そこに凝縮された魔法のエネルギーは散らさねばならん！", "webを取り返してくれたのだな! よくやった、{name}! Lethtendrisは、彼女と同じ類の多くのエルフと同じく、魔法の濫用が我々の世界にもたらす危険に目を閉ざしている。彼らは自分たちが魔法の主人だと信じているが、実は己の中毒の奴隷なのだということに気づいていない。彼女の死は悲しいが、必要なことだった。\n\nありがとう、{name}。webに宿る力は広い範囲へ安全に解き放たせ、その後、今後の魔法の悪用を防ぐためにこれを破壊しよう。", 0x249af7d4, 0x49bd9dd5, 0x20db493a, 0x54c6c753, 0x3dde233f, "....." },
  [7489] = { "Lethtendris's Web", "FeralasのCamp MojacheにいるTalo Thornhoofに、Lethtendris's Webを渡して下さい。", "blood elfのLethtendrisは分を越えた。魔力を集めることにあまりに熱心なあまり、同胞に逆らって陰険な仕組みの装置を作り上げたのだ。Dire Maulの穢れた魔力を吸い上げるためのwebだ。今この時も彼女はその力を集め、敵に向けて解き放とうとたくらんでいる。\n\nLethtendrisは止めねばならない。Dire MaulのWarpwood Quarterで彼女を見つけ、打ち倒し、webを私のもとへ持ってきてくれ。もっと冷静なblood elfたちのもとへ返して研究させるためにな。", "{name}、Lethtendris's Webは持っているか？", "よくやってくれた、{name}。このwebにはDire Maulの魔力が膨大に蓄えられている。Lethtendrisのように無責任な者がその力を操ったなら、どれほどの害が解き放たれるかと恐ろしい。彼女の死は悲しいが、生きているうちに彼女がこのwebを手放すことなどありえなかったことも分かっている。\n\nありがとう、{name}。このwebは、Lethtendrisよりも責任感のある魔法の学徒たちのもとへ送ろう。彼らがその力の新たな守り手となる。", 0x249af7d4, 0x62d2a3d4, 0x15303a66, 0xa9088e0e, 0xdb7d743a, "....." },
  [7490] = { "Hordeの勝利", "Head of OnyxiaをOrgrimmarのThrallのところへ持って行って下さい。", "不可能を成し遂げたな。Black Dragonflightの母竜は、お前の足元で息絶えている。その首を持って、お前の大族長に差し出すのだ。", "<巨大なhead of Onyxiaを目にした瞬間、Thrallの冷静な態度が一瞬だけ崩れる。強大なDoomhammerがあやうく抜き放たれそうになった。>", "これはHordeにとって大いなる勝利だ、{name}。お前は幾度となく大族長に栄誉をもたらしてきた。今度は大族長がお前を称える番だ。", 0x7d8d6308, 0xc65979a5, 0x33ae514c, 0x79883f70, 0x51211934, "....." },
  [7491] = { "皆の目に晒せ", "Valley of StrengthにいるOverlord Runthakを探し出して下さい。", "Overlord RunthakがValley of Strengthでお前の到着を待っている。\n\n<Thrallがあなたに敬礼する。>\n\n民衆を待たせるな、英雄よ。", nil, "報酬を選ぶがいい。そして、お前の輝かしい勝利の祝宴を始めよう。", 0x0f8c7c56, 0x54df7e16, 0x46902d31, nil, 0x4d9c39da, "...m." },
  [7492] = { "Camp Mojache", "FeralasのCamp MojacheにいるTalo Thornhoofと話して下さい。", "FeralasのトーレンのTalo Thornhoofが助けを求めている。詳しいことはほとんど語らなかったが、繊細で……かつ切迫した件のために人手が要るとは言っていた。\n\nHordeに尽くせ、{name}。FeralasのCamp Mojacheへ行き、Taloと話すのだ。", nil, "ああ、{class}が私の呼びかけに応じてくれたのは喜ばしい。あなたの助けが必要なのだ、{name}。そしてそれは、あなたを危険な道へと導くことになるのではないかと恐れている……\n\nDire Maulへと続く道だ。", 0xa6ffc12b, 0x7b82476a, 0xc13a5b92, nil, 0x79feceef, "...m." },
  [7493] = { "始まったばかりの旅", nil, nil, nil, "dragonを討つ者であり、熟練の皮革職人でもあるのか? そなたは驚かせることをやめないな、英雄よ。頭が下がる思いだ。\n\nこれから私が教えることを、どうか受け取ってほしい。この知識は、Black Dragonflightの残りを滅ぼそうというのなら、かけがえのないものとなるだろう。\n\nその母竜の鱗からマントを作るのだ。それはBlackrockの主……Nefarianの燃え立つ吐息から、そなたと仲間たちを守ってくれる。", 0xccab3732, nil, nil, nil, 0x76f38e96, ".mmm." },
  [7494] = { "Feathermoon Stronghold", "FeralasのFeathermoon StrongholdにいるLatronicus Moonspearと話して下さい。", "{name}！Feralasであなたの助けが必要です！\n\n無法者のメイジ、Lethtendrisが、今ではDire Maulと呼ばれる古代エルフの廃墟Eldre'thalasへ逃げ込みました。彼女は危険な魔力を帯びた品を持っているとされ、それは取り戻さねばなりません。\n\nLatronicus Moonspearが、Dire Maulに入ってLethtendrisからその品を取り戻す人手を求めています。\n\nAllianceに尽くしてください！FeralasのFeathermoon StrongholdでLatronicusを探してください。", nil, "よく来た、{name}。会えて嬉しく思うが、この出会いがもっと喜ばしい状況でないことは残念だ。\n\nよく聞いてほしい。そなたに託したい重要な務めがあるのだ……", 0xfdb07f41, 0xe796dea4, 0x353288ef, nil, 0xfe011fb0, "...m." },
  [7495] = { "Allianceの勝利", "Head of OnyxiaをStormwindのHighlord Bolvar Fordragonのところへ持って行って下さい。", "不可能を成し遂げたな。Black Dragonflightの母竜は、お前の足元で息絶えている。その首を持って、大君主に差し出すのだ。", "Utherの髭にかけて！", "長年、私は彼女の魅惑の眼差しに囚われていた。ついに正義が下され、Stormwindの名誉が回復するのを見られるとは! 今日、我々はこの輝かしい勝利を祝おう!", 0xc2d46496, 0x505dad80, 0x560a0c47, 0x770e5d67, 0xe5878ffa, "....." },
  [7496] = { "楽しい時を祝おう", "Valley of HeroesにいるMajor Mattinglyを探し出して下さい。", "Valley of HeroesにいるMajor Mattinglyを訪ねよ、{name}。彼はお前を待っているだろう……", nil, "このような式典で称えられる者はそう多くはない、{name}。どうか報酬を選んでくれ。祝宴を始められるように。", 0x3703d072, 0xdc35ec0b, 0x4f451a8c, nil, 0x5d991116, "...m." },
  [7497] = { "始まったばかりの旅", nil, nil, nil, "dragonを討つ者であり、熟練の皮革職人でもあるのか? そなたは驚かせることをやめないな、英雄よ。頭が下がる思いだ。\n\nこれから私が教えることを、どうか受け取ってほしい。この知識は、Black Dragonflightの残りを滅ぼそうというのなら、かけがえのないものとなるだろう。\n\nその母竜の鱗からマントを作るのだ。それはBlackrockの主……Nefarianの燃え立つ吐息から、そなたと仲間たちを守ってくれる。", 0xccab3732, nil, nil, nil, 0x76f38e96, ".mmm." },
  [7498] = { "Garona: A Study on Stealth and Treachery", "この本を本来の持ち主のところへ返却して下さい。", "書物にはAthenaeumの印が押してある。", "書物を取り戻したのだな！", "素晴らしい働きだ、{race}。もっと本が見つかったら、迷わずここへ戻して欲しい。\n\nそのうち、返ってくる書物に備えてこの辺りを変えて、新しい報酬を追加するつもりだよ。", 0x56d361ae, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7499] = { "Codex of Defense", "この本を本来の持ち主のところへ返却して下さい。", "書物にはAthenaeumの印が押してある。", "書物を取り戻したのだな！", "素晴らしい働きだ、{race}。もっと本が見つかったら、迷わずここへ戻して欲しい。\n\nそのうち、返ってくる書物に備えてこの辺りを変えて、新しい報酬を追加するつもりだよ。", 0x1bbcdca9, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7500] = { "The Arcanist's Cookbook", "この本を本来の持ち主のところへ返却して下さい。", "書物にはAthenaeumの印が押してある。", "書物を取り戻したのだな！", "素晴らしい働きだ、{race}。もっと本が見つかったら、迷わずここへ戻して欲しい。\n\nそのうち、返ってくる書物に備えてこの辺りを変えて、新しい報酬を追加するつもりだよ。", 0xa3796ce9, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7501] = { "光とその用い方", "この本を本来の持ち主のところへ返却して下さい。", "書物にはAthenaeumの印が押してある。", "書物を取り戻したのだな！", "素晴らしい働きだ、{race}。もっと本が見つかったら、迷わずここへ戻して欲しい。\n\nそのうち、返ってくる書物に備えてこの辺りを変えて、新しい報酬を追加するつもりだよ。", 0x62c494c9, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7502] = { "Harnessing Shadows", "この本を本来の持ち主のところへ返却して下さい。", "書物にはAthenaeumの印が押してある。", "書物を取り戻したのだな！", "素晴らしい働きだ、{race}。もっと本が見つかったら、迷わずここへ戻して欲しい。\n\nそのうち、返ってくる書物に備えてこの辺りを変えて、新しい報酬を追加するつもりだよ。", 0x2f56089a, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7503] = { "The Greatest Race of Hunters", "この本を本来の持ち主のところへ返却して下さい。", "書物にはAthenaeumの印が押してある。", "書物を取り戻したのだな！", "素晴らしい働きだ、{race}。もっと本が見つかったら、迷わずここへ戻して欲しい。\n\nそのうち、返ってくる書物に備えてこの辺りを変えて、新しい報酬を追加するつもりだよ。", 0x548d96c8, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7504] = { "Holy Bologna: What the Light Won't Tell You", "この本を本来の持ち主のところへ返却して下さい。", "書物にはAthenaeumの印が押してある。", "書物を取り戻したのだな！", "素晴らしい働きだ、{race}。もっと本が見つかったら、迷わずここへ戻して欲しい。\n\nそのうち、返ってくる書物に備えてこの辺りを変えて、新しい報酬を追加するつもりだよ。", 0xb0e98e7d, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7505] = { "Frost Shock and You", "この本を本来の持ち主のところへ返却して下さい。", "書物にはAthenaeumの印が押してある。", "書物を取り戻したのだな！", "素晴らしい働きだ、{race}。もっと本が見つかったら、迷わずここへ戻して欲しい。\n\nそのうち、返ってくる書物に備えてこの辺りを変えて、新しい報酬を追加するつもりだよ。", 0x195c2263, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7506] = { "The Emerald Dream……", "この本を本来の持ち主のところへ返却して下さい。", "書物にはAthenaeumの印が押してある。", "書物を取り戻したのだな！", "素晴らしい働きだ、{race}。もっと本が見つかったら、迷わずここへ戻して欲しい。\n\nそのうち、返ってくる書物に備えてこの辺りを変えて、新しい報酬を追加するつもりだよ。", 0xb075a617, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x8b9e3b1a, "....." },
  [7507] = { "Nostro's Compendium", "Nostro's Compendium of Dragon SlayingをAthenaeumに戻して下さい。", "あなたは非常に重要なものを見つけた。この本は、これまでに見たどの本とも違う。\n\n何者か、あるいは何かがAthenaeumの封印を打ち砕いたように見える。中の文字は乱れていて、ほとんど読めない。", "ああ、我らの最も偉大な編纂書の一つだ。これは長い間行方知れずになっていたのだ。", "この本は闇市場でかなりの金になっただろうな、{name}。とりわけ守りの封が破られ、聖なるページに収められた知識を読み解くだけの知性を持つ者になら、dragon退治の秘密が見えるようになっているのだからな。\n\n大いなる報酬がふさわしいかもしれん……いや、手に入れるのに途方もない労を要する報酬がな。\n\n<Lydrosがにやりと笑う。>", 0xd019ffa4, 0x30367b5a, 0x9a80f073, 0x9b3492ba, 0x2374beb3, "....." },
  [7508] = { "Quel'Serrarの鍛造", "Lorekeeper LydrosにDull and Flat Elven Bladeを渡して下さい。", "この責務を引き受けようと思うのならば、刃のこぼれた剣をLydrosに示して下さい。", "素晴らしい、では始めよう……", "あの竜の住処へ何とか入れたら、竜の炎の息で剣を熱し、最後に竜の血で焼き入れを行うのだ。その剣は君専用として絆を結んであげよう。", 0x700c7e24, 0xd02c38a3, 0xd42b2fc9, 0xd2ab567a, 0x0d6cb539, "....." },
  [7509] = { "Quel'Serrarの鍛造", "OnyxiaにUnfired Ancient Bladeへ炎を吐かせなければならない。それができたら、熱を帯びたHeated Ancient Bladeを拾う。注意すること。Heated Ancient Bladeはいつまでも熱いままではない。時間が肝心だ。\n\n私のところへ戻る前の最後の手順は、その獣を倒し、Heated Ancient Bladeをその死体に突き立てることだ。\n\nこれを成し遂げれば、Quel'Serrarはあなたのものになる。", "unfired ancient bladeをOnyxiaの巣へ持って行き、彼女と戦え。\n\nbladeを熱するには策を用いる必要がある。戦いの最中、彼女はきっと炎の吐息でお前を焼き尽くそうとするだろう。unfired ancient bladeを近くに突き立て、炎の吐息がbladeを熱してくれることを祈るのだ。それを生き延びたら、今や熱を帯びたheated ancient bladeを拾い上げ、竜に止めを刺せ。\n\nheated ancient bladeをくすぶる亡骸に突き立て、treated ancient bladeを鍛え上げるのだ。", "いつの日か、また誰かがあの虹色に輝く刃を振るうことだろう。", "<Lydrosが何か聞き取れないことをつぶやく。>\n\n約束どおりだ、{class}。Quel'Serrarの剣だ。", 0x700c7e24, 0x4b267fc9, 0xb2e66075, 0x90d8fc2b, 0x41ddcb19, "....." },
  [7521] = { "Thunderaan the Windseeker", "Thunderaan the Windseekerを牢獄から解き放つには、Bindings of the Wind Seekerの右半分と左半分、Elementiumのインゴット$N1本、そしてEssence of the FirelordをHighlord Demitrianに差し出さなければならない。", "我が知ることはすべて話した、{name}。elementiumを見つけねばならぬのはそなただ。Firelordの肉体を滅ぼさねばならぬのもそなただ。\n\nこれを成し遂げ、Thunderaanの祝福を得よ。", "必要とあらば、世界を跪かせてしまえ！", "夢の中でさえ、この日を予見しようとはしなかった。\n\n見よ、定命の者よ。\n\n存在そのものより古き御方を見よ!\n\nTITANとも神とも相対した御方を見よ!\n\n蘇りたまえ、我が主よ! その枷を打ち破りたまえ!", 0x30d08f81, 0x7d1b0cf0, 0xaaceb8e0, 0xb1d1afb9, 0x6900d53f, "....." },
  [7541] = { "Hordeへの奉仕", nil, nil, nil, "お前が持ってきたペンダントを学者たちが調べるには時間がかかる。だが、Hordeへの奉仕に対して、ささやかな礼を渡したい。\n\nありがとう、{name}。お前の行いはお前自身に、そして我々に名誉をもたらす。", 0x585442a8, nil, nil, nil, 0x4652c53f, ".mmm." },
  [7562] = { "Mor'zul Bloodbringer", "Burning SteppesにいるMor'zul Bloodbringerと話して下さい。", "{name}、お前の闇の術への探求は深い。異界の住人を従える力もこれほど強くなった……名高いdreadsteedsの一頭を己に縛りつける準備ができたのかもしれん。\n\nその獣を故郷から呼び出す儀式には大いなる力と資源が要る。だが、あの伝説の騎獣を支配したいと望むなら、Mor'zul Bloodbringerと話せ。奴はBurning SteppesのAltar of Stormsの近くに野営している。\n\n行け、{name}。このクエストは危険なものとなろうが、お前ほどのウォーロックは危険にひるみはしない！", nil, "ごきげんよう、{name}、ようこそ。あなたも私と同じく、Altar of Stormsの近くで学ぶために来たのか。おそらくは何か隠された目的のためにその力を利用しようと……\n\nそれとも……私と話すために来たのか? ああ、そうだろうと思う。\n\ndreadsteedを乗りこなしたいのだな? それは容易な務めではない。少なからぬ血と汗……そしてもちろん金がかかる。だがXorothのdreadsteedは勝ち取るに値する褒美だ。興味があるなら、このまま聞くがいい……", 0x70b8af5f, 0xf3dc644e, 0xffd05978, nil, 0xd348df70, "...m." },
  [7563] = { "怒りの血", "Raging Beast's Bloodのボトル30本をBurning SteppesのMor'zul Bloodbringerに渡して下さい。", "dreadsteedsは別の世界、燃え盛るPlains of Xorothに棲んでいる。あの名高い獣の一頭を縛るには、強力なglyphを発動させねばならん。そのglyphを羊皮紙に記してやることはできるが、まずは特別なインクが要る。\n\n遠いWinterspringに、フクロウの獣の一族が棲んでいる。かつては清らかな生き物だったが、Darkwhisper Gorgeから漂う悪魔の気に狂わされ、今では狂乱して雪原をさまよっている。\n\nその血こそ、お前の羊皮紙を記すインクに要るものだ。それを持ってこい。", "荒れ狂うowl beastsを見たか、{name}？ あの獣たちの魔力は強く、その苦しみに歪んだ体を流れる血に凝縮されているのだ。", "ああ、すごくいいね。この血を蒸留してインクにし、約束していた羊皮紙に使うんだ。それと私の分もほんの少しとっておくつもりさ。この血は実に至福の味だと聞いたからね……", 0x7adddd9f, 0x37c14049, 0x922b3e68, 0x41ff93b4, 0xa1bf07d8, "....." },
  [7564] = { "Wildeyes", "Burning SteppesのGorzeeki WildeyesにCase of Bloodを渡して下さい。", "我が従者Gorzeekiはいくらか腕の立つ錬金術師だ。羊皮紙に必要なインクを用意してくれる。君が持ってきてくれた血をまとめておいたから、仕事にとりかかれるようGorzeekiのところへ持って行ってくれ。", "何か持ってきてくれたのかい？ 大きくてジューシーな蜘蛛じゃないよね？ それともゴキブリかな？ まだ生きてるといいなあ……生きてるうちに噛むのが大好きなんだよ……", "おや、血じゃないか。ならば主人のMor'zulのものに違いない。あの方はこれに目がなくて、流れるのを見るのが大好きだからね。もっとも、私は小さなげっ歯類の血管を流れているほうが好みだけど。そのほうが温かいままなんだ……欲しくなるまでね。\n\nこれは強力な血だ。Mor'zulはdreadsteedを召喚する羊皮紙をまた作っているに違いない! なんてわくわくするんだ!\n\nもしそれが本当で、あなたが儀式を行うつもりなら……血よりずっと多くのものが必要になるよ、友よ。", 0xb9b269a3, 0x5a9443c3, 0xe186564e, 0x431c1ea4, 0x17f66757, "....." },
  [7581] = { "牢の接着剤", "FeralasのDire Maulへ行き、Warpwood Quarterに住むWildspawn SatyrからSatyr Blood 15本を手に入れて下さい。それを終えたらTainted ScarのDaioのところへ戻って下さい。", "Doomguardの牢獄を縛るものを、下級の悪魔どもから手に入れてこなければならない。\n\nDire Maulに巣食うWildspawn satyrのbloodがちょうどよいだろう。凝固したbloodがHederineの欠片をつなぎ合わせ、水晶の牢獄に力を与えるのだ。", "Wildspawn satyrの血でなければ役に立たない。", "ああ、最高の仕事をしてくれたね。この血がDoomguardの魔法防御を抑えてくれる。", 0x0da2867e, 0xf791ccbd, 0x4a0a73cf, 0x88fa6d3b, 0x2845db33, "....." },
  [7582] = { "牢の覆い", "WinterspringのDarkwhisper Gorgeへ行き、渓谷を支配しているHederine demonからTears of the Hederine 5つを手に入れて下さい。それを終えたらTainted ScarのDaioのところへ戻って下さい。", "Mount Hyjalの麓に巣食うHederineの悪魔どもは、強力な邪悪の毒を分泌する。それが熟すと、魔法を寄せつけない密な水晶へと固まるのだ。この水晶はTears of the Hederineとして知られるようになった。\n\nこの素材で作られた牢獄の壁は、Doomguardの途方もない力をもってしても破れはしない。\n\nWinterspringのDarkwhisper Gorgeへ赴き、Tearsを取り戻してこい。", "The Hederineは戦わずして大切な宝石を手放しはしないぞ、{name}。", "Wildspawnの血を結晶と結合させるだけで、牢の使用準備が完了するだろう。", 0xc7e97794, 0x57e4bc82, 0xc64e1f45, 0xc76bfc02, 0xa09498ea, "....." },
  [7583] = { "鎮圧", "Tainted Scarへ踏み込み、Doomguard Commanderを見つける。\n\nDoomguard CommanderにGlowing Crystal Prisonを使う。悪魔は捕獲から逃れようとして猛烈な攻撃を仕掛けてくるので、覚悟しておくこと。\n\n成功したら、Imprisoned DoomguardをTainted ScarのDaioのところへ持ち帰って下さい。", "牢獄の準備は整った。いよいよこの務めで最も難しいところだ。\n\nこの水晶の牢獄を使って、Tainted Scarの中でDoomguard Commanderを見つけ出し、捕らえなければならない。\n\n警告しておく！Doomguardは狡猾で恐ろしい敵だ。お前が封印の儀式を始めれば、お前を滅ぼそうとしてくる。封印から逃れようと、激しく暴れ回るだろう。\n\n奴はお前だけを狙ってくるぞ、{name}。だからこそ、お前を生かしておける仲間を連れていくことを勧める！", "うむ？ それで？", "頼んだ通りにやってくれたんだね。この獣を呼び出し操る知識を手にする用意ができたな。", 0x46ccd505, 0xfc958e98, 0x8267dd8d, 0xefa60722, 0x3fa4c997, "....." },
  [7601] = { "Nibyの命令", "FelwoodのImpsyと話して下さい。", "infernalの従者を召喚する秘術を教わりたいのなら、Kroshiusを滅ぼし、その燃える亡骸からinfernal coreを持ってこなければならない。だが、これは言うほど容易くはない。Kroshiusはほとんど燃え尽きてしまっている。奴の亡骸に再び火を灯し、瓦礫から蘇らせねばならないのだ。そのためには、他の悪魔的な存在からいくつかの材料を集める必要がある。\n\n私のimp、Impsyがお前を導いてくれるだろう。", nil, "やれやれ、またかよ。", 0xfdb31e0d, 0x0c9d6772, 0x56c5c901, nil, 0x34ba2cb4, "...m." },
  [7602] = { "Flawless Fel Essence", "FelwoodのImpsyは、3つの異なる場所から採れたFlawless Fel Essencesを3つ持ってきてほしいと言っています。\n\nAzsharaのLegashi Satyrsが、その地方のFlawless Fel Essenceを持っている。JaedenarのJaedenar Legionnairesが、その地方のFlawless Fel Essenceを持っている。Blasted LandsのFelguard Sentriesが、その地方のFlawless Fel Essenceを持っている。\n\nFlawless Fel Essencesを回収し、FelwoodのImpsyのところへ戻って下さい。", "Kroshiusを蘇らせるつもりなら、Fel fireが要るよ。Fel fireは作れるけど、材料がいくつか必要なんだ。\n\n世界の三つの異なる地域から、完璧なFelのエッセンスを持ってきてほしい。\n\n一種類目はAzsharaのLegashi Satyrs、二種類目はJaedenarのJaedenar legionnaires、三種類目はBlasted Landsのfelguardの歩哨が持ってるはずさ。\n\nエッセンスを一種類ずつ持ってきてくれたらFel fireを作ってあげる。それでKroshiusを蘇らせられるよ。", "誰にも言うんじゃないぞ、Nibyは間抜けなんだ。", "ちょっと待っててくれ。精髄をFelの火に結合するから。", 0x624eeeec, 0xbe474b63, 0x2e3d35df, 0x48088787, 0x56418681, "....." },
  [7603] = { "Kroshius' Infernal Core", "FelwoodのShatter Scar ValeでKroshiusの亡骸を探す。亡骸を見つけたら、その近くでFel Fireを使い、Kroshiusが戻ってくるのを待つ。infernalが目覚めたら倒し、その死体からKroshius' Infernal Coreを奪う。\n\nKroshius' Infernal CoreをFelwoodのNiby the Almightyのところへ持ち帰って下さい。", "Kroshiusは北東のShatter Scar Valeに山となって横たわっている。このFel fireを持って行き、奴の亡骸に使え。その火が倒れたinfernalを蘇らせるはずだ。\n\nその時点で、奴がお前と、お前が連れてきた仲間たちを皆殺しにするだろうと私は踏んでいる――信じろ、仲間は連れていきたくなるはずだ。\n\n万が一、奇跡的にKroshiusを倒せたら、そのinfernal coreを取ってNibyのもとへ戻れ。", "迷子にでもなったのか？", "契約は契約だ! 早いとこ、これを持っていって書き留めとけ。時間がないんだ! 私の最大呪文の時がやって来たのだ!", 0x9fcd3fbe, 0x5b568bf2, 0x429fc5de, 0x3f3b06cd, 0x61c43582, "....." },
  [7604] = { "法的契約", "Sulfuron の設計書を受け取りたいのであれば、Thorium Brotherhood Contract を Lokhtos Darkbargainer に返して下さい。", "署名者はこれにより、Thorium Brotherhood (TB Ltd.)に届けられた Sulfuron インゴットが正規品であり複製でないことを証明する。また、署名者は Sulfuras を建築し、鋳造し、発見し、制作し、売却し、あるいは摂取を企図した結果として発生するいかなる損害も受け入れるものとし、これについては TB Ltd. の過失あるいは責任とはならない。\n\nこの契約に署名することにより、ここに記載された全条項に同意するものとする。\n\n_  署名:", "取引成立か？", "あんたと商売ができて何よりだったよ、{name}!\n\nTB Ltd.を代表して、Sulfurasの捜索に幸運を祈るぞ!", 0xb3e013a8, 0xb4f357b1, 0x9f3945b5, 0xf707cff6, 0xa3184ea3, ".....", nil, nil, 0xc22a16e9, nil, nil },
  [7621] = { "警告", nil, nil, nil, "プリーストよ、そなたはこれより、己の力のすべてを試す厳しい試練の数々を受けることになる。\n\n私が語る話に耳を傾けることを勧める。\n\n心せよ、この務めは一人で成し遂げねばならぬ。仲間たちは離れて待つことを勧める。外部の者による干渉は、最も厳しい罰を招くだろう。\n\n運命がそなたを、そなた一人をここへ導いた。誇りを持って戦え。光を宿すのだ。", 0x68902ac5, nil, nil, nil, 0x08834217, ".mmm.", nil, nil, nil, nil, 0x742079ec },
  [7622] = { "光と影の均衡", "Peasantsが$N2人殺される前に、$N1人を救出する。この任務を果たしたら、Eris Havenfireと話して下さい。\n\nDeath Postを見れば、何人のPeasantsが殺されたかを確認できます。", "私にできなかったことを成し遂げてほしい。Stratholmeから逃げる途中で斬り倒された農民たちを救うのだ。\n\n彼らは光の方へ歩いていく。君は彼らを生き延びさせねばならない。倒れる者が多すぎれば、私たちの呪われた存在は続くだろう――君は失敗したことになる。\n\n君が身につけたあらゆる技、祈り、呪文が試されることになる。光が君を守らんことを、{name}。", nil, "あなたの強い忍耐と勇気は驚嘆すべきものです、{class}。Splinter of Nordrassilを持つ資格を手に入れたのですよ。ただもうひとつ仕事が残っています、Eye of Shadowを取り戻さねばなりません。世界中を探し回るのです。", 0xf2986d90, 0xf7f49555, 0x5abd49cb, nil, 0x5e59767f, "...m.", nil, nil, nil, nil, 0x9fefa0b4 },
  [7623] = { "Lord Banehollow", "Burning SteppesのGorzeekiからShadowy Potionsを購入する。\n\nそのポーションを使ってJaedenarを通り抜け、Lord Banehollowと話して下さい。", "Mor'zulの話じゃ、あんたはXorothへのポータルを開きたいんだってね。それには、Xorothian stardustが要る。Azerothじゃなかなか見つからない代物だよ！\n\n少しは持っていそうな者が一人いる。Shadow Councilの本拠地、JaedenarにいるLord Banehollowさ！彼と話せば、stardustを譲ってくれるかもしれない。\n\nでも、Jaedenarへ行くなら、Shadow Councilならではの悪の気配をまとって身を隠さないといけない。それにはあたしのshadowy potionsが要る。それには代金がかかるよ……", nil, "我が忍耐は千年にも及ぶのだ、{class}。だがお前への忍耐が一瞬より長く許されると思うなよ……", 0xe235f822, 0xa034cca0, 0x1e3a4885, nil, 0xc224e623, "...m." },
  [7624] = { "Ulathek the Traitor", "Ulathekと対決し、Traitor's HeartをJaedenarのLord Banehollowに渡して下さい。", "我が寵愛を得たいと？ならば我のために殺すがよい。\n\n我が僕Ulathekは、我の前で卑屈にひれ伏しながら、その裏でXorothのLord Hel'nurathと陰謀を巡らせている、哀れな奴だ。Hel'nurathはここで我が力を奪おうとたくらんでおり、Ulathekはその密偵なのだ……\n\nそなたが仕えるのは我であり、我が敵ではないと証明せよ。西のShadow Holdにある奴の部屋でUlathekと対峙せよ。奴の秘密は知っていると告げ、恐怖が奴を捕らえるさまを見届けるがよい。それから、裏切り者の心臓を我がもとへ持ってこい！", "Ulathekの心臓の味が、もう唇に感じられるわ。裏切り者の肉は実に甘美なのよ……", "ああ、なんと素晴らしい! 一週間腐らせれば、このheartは実に美味な馳走となるだろう! Ulathekの首も取り寄せて、食べる間、目の前に置いておこうか……\n\nそなたは私に尽くしてくれた、{class}。ゆえにそなたへの我慢も増した。ほんのわずかにな。", 0x4b8d3a3d, 0xd5b88347, 0xe4198aaa, 0x01497fb4, 0x88afdb8f, "....." },
  [7625] = { "Xorothian Stardust", "Ur'danからXorothian Stardustを購入し、Burning SteppesのGorzeeki Wildeyesに渡して下さい。", "それで、Xorothian stardustを求めて我がもとへ来たと？我が宿敵Hel'nurathの領域、Xorothへのポータルを開きたいと申すか？奴の大事なdreadsteedsの一頭を盗み出すつもりなのかもしれんな？\n\nよかろう。我が僕Ur'danがXorothian stardustを蓄えている。奴から手に入れるがよい……その代償を払えるならな。", "Jaedenarには行ったかい、{name}？ Lord Banehollowからstardustは手に入れたかい？", "あった! 本当に手に入れたなんて信じられないよ! あのDreadlordと大きな取引をしたか、大金を払ったか、その両方に違いない!\n\nMor'zulはもうすぐインクを手にする。そうすればついに紋章の羊皮紙を作れる。あなたはXorothへの門を開き、名高いdreadsteedの一頭を引きずり出せるんだ!", 0x545c6ef8, 0x4baa8da0, 0xfa59e779, 0x95c60713, 0x7a7c7622, "....." },
  [7626] = { "Bell of Dethmoora", "Burning SteppesのGorzeeki WildeyesにElixir of Shadow Power 10本を渡して下さい。", "Bell of Dethmooraは、今は亡きウォーロックDethmoora Darkeyesにちなんで名付けられたもので、Circle of Greater Summoningを作るのに必要な3つの道具の一つだ。WheelとCandleと正しく同調させれば、これらの品は莫大な秘術の力を導く。\n\n我が僕Gorzeekiならそのようなbellを作れるが、それには大量のelixirs of shadow powerが要る。錬金術師からそのelixirsを手に入れ、Gorzeekiのもとへ持っていけ。", "秘薬は持ってるかい、{name}？ Mor'zulから聞いたが、Bell of Dethmooraが必要なんだって？ あれを作るには影の力がたっぷり要るからね！", "大変よろしい! このエリクサーを手に入れるのが、あまり大変でなかったならよいのだが。錬金術師というのは、ときに自分の作ったものにひどく物惜しみをするからね……\n\n鐘は私が作り、あなたが儀式の備えを整えるまで預かっておこう。", 0x8f2b3d75, 0x37da1da0, 0x4fb5aaf1, 0x3c4ced13, 0x93c74315, "....." },
  [7627] = { "Wheel of the Black March", "Large Brilliant Shard 6つとDark Iron Ore 25個をBurning SteppesのGorzeekiに渡して下さい。", "Wheel of the Black Marchは、Circle of Greater Summoningに必要な荒々しい力を蓄え、導くものだ。Gozeekiがwheelを作るには、エンチャンターから手に入れるlarge brilliant shardsと、熟練の鉱夫から手に入れるdark iron oreの両方が要る。\n\nこれらを手に入れ、我が僕のもとへ持っていけ。", "Wheel of the Black Marchは簡単には作れないし、材料もたくさん要るんだ。もう集まったかい？", "あった! dark iron oreはBlackrockの奥深くでしか見つからないと聞くし、このshardsを見つけるのも楽ではなかっただろう。あなたたちウォーロックの熱心さには、いつも感嘆させられるよ。その力をすべて虫捕りの技に注いでいたなら、ああ……どれほどの饗宴を楽しめたことか!\n\nすまない、少し脱線した。車輪は私が作り、あなたが儀式の備えを整えるまで預かっておこう。", 0x1b0d9a93, 0x3e273a7a, 0xd77dc84e, 0xf3d47d02, 0xf3df9f45, "....." },
  [7628] = { "Doomsday Candle", "Burning SteppesのGorzeeki WildeyesにBlack Dragonscale 35枚を渡して下さい。", "Doomsday Candleは炎を蓄え、お前の儀式を乱そうとする者どもにそれを浴びせる。Circle of Greater Summoningを作る時、candleに火が灯っていれば、迷い込んだ悪魔どもはその炎に焼かれるのだ！\n\nその炎を封じ込めるのは容易ではなく、黒い竜のscalesに宿る精髄が要る。皮はぎ職人からそのscalesを手に入れ、Gorzeeki Wildeyesのもとへ持っていけ。", "dragonscalesは持ってきたかい、{name}？ それが揃うまではロウソク作りに取りかかりたくないんだ……さもないと、キャンプごと吹っ飛ばしちまうかもしれないからね！", "ああ、すごくいいね。蝋燭の火を抑えるのにこれが必要なんだ。鱗が手に入ったから、蝋燭を作って、Circle of Greater Summoningの儀式を始める準備が整うまで保管してやるよ。", 0x365c7d38, 0x95f646d3, 0xb19711bd, 0x45a89c38, 0x940d3218, "....." },
  [7629] = { "インプのお届け", "Scholomanceの錬金実験室へImp in a Jarを持って行って下さい。羊皮紙が出来上がったら、Gorzeeki Wildeyesに容器を返して下さい。", "Mor'zulの羊皮紙には、もう一つ工程が要るんだ。Xorothian stardustを染み込ませた紙が必要でね。それで……残念だけど、ここじゃそれができない。道具がないんだよ！\n\nでも、必要なものが全部揃った錬金術の実験室がある。PlaguelandsのCaer Darrow島にある、Scholomanceの中さ。\n\nあたしは行けないけど、ほら――このjarを持っていって。中にはなかなか賢いimpが入ってる。錬金術の実験室でそいつを出してやれば、羊皮紙に染み込ませてくれるよ。", "Scholomanceには行ったかい、{name}？ impはもう巻物にstardustを染み込ませたかい？", "ああ、よかった。J'eeveeが羊皮紙を作ったのだな。Scholomanceはどうだった? 魅力的だったろう? それにあそこの虫ときたら……美味いと聞くぞ!\n\nよくやった、{name}。それに私のjarを返してくれてありがとう。長いこと持っていたものでね……売り物ではないぞ!", 0x671d5339, 0x29da576a, 0xcfb8f80b, 0x60220738, 0xf1d0309a, "....." },
  [7630] = { "Arcanite", "Burning SteppesのGorzeekiにArcanite Bar 3本を渡して下さい。", "これでBell、Wheel、Candleができたから、今度は黒い磁鉄鉱を作らないとね。儀式の間、他の儀式の道具がもし駄目になったら、それを保つのにその磁鉄鉱が要るんだ。\n\n磁鉄鉱を作るには、arcaniteが必要だ。持ってるかい？持ってないなら……錬金術師からarcaniteを手に入れてこないといけないね。\n\narcaniteが手に入ったら戻っておいで。そうしたら黒い磁鉄鉱を作ってあげるよ。", "arcaniteは持ってるかい、{name}？ それさえあれば、黒い磁鉄鉱を作ってやれるよ。", "でかした! よくやった! これで磁石を作れるぞ。最終的にCircle of Greater Summoningを作る儀式の準備が整ったら、確実に儀式が失敗しないようにしてくれる磁石が欲しくなるだろうよ。", 0xc51a3c6d, 0xe8bccc58, 0xbe1126f3, 0xe4b09957, 0x52e54ca1, "....." },
  [7631] = { "Dreadsteed of Xoroth", "Mor'zul's Instructionsを読んで下さい。Xorothian Dreadsteedを召喚して倒し、自分の魂に束縛して下さい。", "準備はすべて整った。今度はCircle of Greater Summoningを作る儀式を行い、それからXorothian stardustを染み込ませた羊皮紙を使って……Xorothへのポータルを開かねばならない。\n\n儀式の手順は巻物に書いておいた。よく読んでおけ。成功したければ、一つ一つの手順を正確に行わねばならんからな。\n\n幸運を、{name}。そして敵どもの魂が、速やかにお前のshard pouchへと収まらんことを。", nil, "Xorothian Dreadsteedの魂は打ち負かされた。その幽玄な脇腹には怒りが脈打っているが、この獣の魂が自分のものになったことが分かる……\n\nそれはあなたの心に闇の魔法をささやき、dreadsteedを召喚する知識をあなたの内に植えつける。", 0x006280f0, 0xe613427f, 0xe954e091, nil, 0xc275b0a3, "...m." },
  [7632] = { "古代の葉", "Ancient Petrified Leafの持ち主を探して下さい。頑張って下さい、{name}。世界は広いのです。", "このleafの表皮は明るい緑色に光っている。表面はひどくしわが寄っていて、いくつもの葉脈やしわが浮き出ている。\n\n推測するなら、このleafは古く強大な何かから落ちたものだろう。\n\nこのleafの元の持ち主を探すべきかもしれない。", "<Vartrusがうめく。>", "もちろん自分のleavesは見分けがつく。これを見ろ! 完璧な状態だ。\n\n返してくれるとは、なんと殊勝な、{class}。\n\nそなたが我々の役に立ち、我々がそなたの役に立つこともあるかもしれん。", 0x6c703ca7, 0x22a42d5f, 0xa0504cee, 0x8301899b, 0x54240120, "....." },
  [7633] = { "紹介", nil, nil, nil, "そなたの勤勉さと誠実さは見届けたぞ、{class}。\n\n我らはAncients、かつて偉大であったこの森の守護者だ。10,000年前、ArchimondeとBurning LegionがHyjalへ進軍した折、我らの肉体は滅ぼされた。しかし、我らの魂は損なわれずに残っておる。\n\n我らが与えられる務めがある。成し遂げれば、Ancientsの秘密がそなたに明かされる務めだ。\n\n心得よ。これらの務めを果たしたなら、ただこの岩へ戻るがよい。さすれば我らはその呼びかけに応えよう。", 0xcffb713f, nil, nil, nil, 0xfe0d07f1, ".mmm." },
  [7634] = { "Ancient Sinew Wrapped Lamina", "Hastat the AncientはMature Blue Dragon Sinewを持ってくるよう頼んでいます。腱を見つけた場合は、FelwoodのHastatに渡して下さい。", "ごきげんよう、{class}。我はHastat、Ancient of Loreである。遥か昔に失われた知識を我は保っておる。\n\nしかるべく結び合わせれば、我が葉の一枚は、この$N1年見られなかったほどの矢筒となろう。Ancientsの弓と共に用いれば、計り知れぬ力を授けうる矢筒だ。\n\n成体の青い竜のsinewを持ってここへ戻れ。さすればこの矢筒はそなたのものとなろう。", "よく戻った、若き{class}よ。", "私の葉が、害悪からの防御をそなたの矢にもたらさんことを。そなたの矢が真実を射貫かんことを。我らの世界の敵が討たれんことを。", 0xf7d950a8, 0x21868862, 0x181cee2c, 0x2ec24b6d, 0xaf5c947d, "....." },
  [7635] = { "相応しい弦", "Stoma the AncientはMature Black Dragon Sinewを持ってくるよう頼んでいます。腱を見つけた場合は、FelwoodのStomaに渡して下さい。", "Vartrusがそなたに、Ancientsの弓を作るための杖を授けるやもしれぬ。だが、弓を仕上げるのに要る弦に魔力を込められるのは我だけだ。\n\nたやすい務めだ、ちっぽけな者よ。成熟した黒い竜を倒し、その骨からsinewを取り出せ。そのsinewを我がもとへ持ち帰れば、ほぼ壊れることのない弓弦へと魔力を込めてやろう。", "そなたならblack dragonを見つけて討つのに、さほど苦労はせぬはずだ、{name}。無駄話で我の時間を浪費させるでない。", "実に忌まわしいdragonだったのだな、こいつは。このsinewは邪悪の臭いを放っている。\n\nこの肉から汚れを清め、しかるべきエンチャントを施すまで、少し待て。", 0x82676768, 0x3a73fecf, 0xff405978, 0x54b8d902, 0x7943c248, "....." },
  [7636] = { "Ancientsの棒", "次の4体の悪魔の堕落者を見つけ出し、滅ぼさなければならない。\n\nSimone the Seductress。\n\nKlinfran the Crazed。\n\nSolenor the Slayer。\n\nArtorius the Doombringer。\n\nこれらの者を滅ぼし、その首を持ってFelwoodのVartrus the Ancientのところへ戻って下さい。\n\n居場所の手がかりは、持ち物の中のPetrified Barkを参照して下さい。\n\nこの任務は必ず一人でやり遂げなければならない。", "Burning Legionの手先どもは、今もこの世界で活動しておる、{class}。奴らは触れるものすべてを穢す。自然は奴らのそばで萎れ、嘆くのだ。\n\n悪魔の穢し手どもを追い詰め、滅ぼすのだ、{name}。心せよ、奴らとは一人で戦わねばならぬ。さもなくば奴らは逃げ去る。そなたが一人でいる限り、奴らはそなたを滅ぼそうとするであろう。奴らを打ち、その傲慢を苦しみに変えてやるのだ。\n\n我がbarkの一片を授けよう。その刻印がそなたを標的へと導くであろう。奴らの首を持ち帰れ。", "奴らの変装に騙されるな！", "我らのためによく働いたぞ、{name}! この棒を持って行き、Stomaの作る弦と組み合わせるのだ。ひとつとなれば、恐るべき武器となる。", 0xe66e38c8, 0x260f60be, 0x3e1d6949, 0xf436c2b1, 0x30e4645c, "....." },
  [7637] = { "犠牲の重視", "Ironforgeへ行き、High Priest RohanのExorcism Censerを手に入れて下さい。手に入れるためには金貨150枚の寄付が必要です。", "この務めに備えるには、まずしかるべき犠牲と裁きを示さねばなりません……とりわけ犠牲を。\n\nこの務めのために、High Priest Rohanのexorcism censerを手に入れなければなりません。善く正しい目的のために使うものではあっても、それにはしかるべき対価を払わねばならないのです。\n\nIronforgeへ赴き、High Priestと話してください。censerを失う埋め合わせになるだけの十分なお金を持っていけば、それがあなたのしかるべき犠牲を示すことになります。\n\nさあ行きなさい、{name}。時間は大切です。", "ようこそ、高貴なるパラディンよ！ 私の信頼する香炉に最も新しい香を詰め、あなたのために三度祝福しておきました。あなたの寄付は、Ironforgeで新しい香炉を作るためだけでなく、貧しい人々のために減りつつある食料の蓄えを補うためにも役立つのです。", "祝福があらんことを、友なる{class}よ! あなたの寄進は必要とされていたものをはるかに超えている。あなたの犠牲は、我々が失ったものを取り戻す助けとなるだけでなく、ここIronforgeで最も困窮している者たちを助ける助けにもなる。\n\nさて、この香炉をこの先の必要に備えてきちんと整えたか、確かめさせてくれ……", 0xe1e9601f, 0x7e3b4971, 0xc697a1be, 0x6c931247, 0x92282285, "....." },
  [7638] = { "Lord Grayson Shadowbreaker", "StormwindのCathedral DistrictにいるLord Grayson Shadowbreakerと話して下さい。", "{name}、長らく待ち望んでいたであろうものを手に入れるために何が必要か、学ぶ時が来た……そなたの軍馬だ。\n\nここStormwindのCathedral DistrictにいるLord Grayson Shadowbreakerと話すがよい。パラディンが最も信頼する乗騎の奥義だけでなく、そなた自身の乗騎を得るために待ち受ける試練へも、彼が導いてくれるであろう。\n\nこの試練でのそなたの健闘を祈る。光のために、気高き同胞よ！", nil, "会えてうれしいぞ、{name}。そなたが軍馬を手に入れる方法についての知らせを待っていたことは知っている。そしてついに、その時が来た。\n\nそなたはさまざまな形で試されるであろう。だが何より試されるのは、目の前に立ちはだかる数多の障害を乗り越えようとする意志だ。これらは学びのための訓練ではない。そなたの器は、もはや単なる教育的な試験を超えている。そなたは、これまで生涯をかけて戦ってきた悪の手から、未来の伴侶を救い出さねばならぬ。\n\n心せよ、そなたの時が来たのだ！", 0x74c8e64a, 0x3b1a14c9, 0x0ec8aced, nil, 0xa28a3953, "...m.", nil, nil, 0x2123d8f1, nil, nil },
  [7639] = { "然るべき審判を示すために", "StormwindのCathedral DistrictにいるLord Grayson ShadowbreakerのところへExorcism Censerを持ち帰って下さい。", "私の祝福と共に、censerを持って行きなさい。私自身、いくつもの悪魔祓いでこれを使ってきました。これから待ち受ける困難な務めでも、きっとあなたの役に立つでしょう。\n\nさあ、StormwindのLord Grayson Shadowbreakerのもとへ戻りなさい、{name}。あなたのクエストは彼と共に続きます。", "お帰りなさい、{name}。exorcism censerは手に入りましたか？", "よし、これでいい。この過程で、そなたは幾度となく犠牲を払う行いを求められるだろう。そなたがまさにそれを厭わぬと見て、私は嬉しく思う。犠牲は、パラディンであることの務めを果たすうえで欠かせない要素だ……とはいえ、そなたに説教する必要もあるまい。\n\nさて{name}、そなたは自らの行いにおいて然るべき裁きを示さねばならぬ。そのために、この香炉は、我々が失った地の苦しむ魂へその裁きを下すための器となる。", 0xf5657bcb, 0x9f1f1c9b, 0x9b13b868, 0xcfa1dede, 0x2f09636b, "....." },
  [7640] = { "Terrordaleの町の除霊", "Terrordaleを苦しめている霊を払うためにExorcism Censerを使用して下さい。Terrordale Spirit 25体を退治したら、StormwindのCathedral DistrictにいるLord Grayson Shadowbreakerのところへ戻って下さい。", "Eastern PlaguelandsのTerrordaleの穢れた地から取った土をひとつまみ、censerに加えておきました。これからこのcenserを使って、そこで霊の混乱と乱れの兆しを見せている場所を探すのです。霊界の苦しみの下で物質界が歪み、地面に染み込む緑のオーラを探し、censerを使って悪霊を追い払ってください。\n\nそこの霊たちに十分な裁きを下したら、次へ進む準備が整うでしょう。", "また会えて嬉しいです、{name}。Terrordaleでのお務めは終わりましたか？", "よくやった、{name}。闇に住まう者たちに光の裁きを下すことは、気力と熱意をもって臨まねばならぬ務めだ。そなたはIronforgeでの犠牲と、Terrordaleの魂たちへの裁きによって、まさにそれを成した。\n\n次の一歩では、犠牲と裁きの両方が再び求められる。Darkreaverと呼ばれるDeath Knightに今なお仕える、倒れた軍馬の魂を取り戻そうとするのだからな。", 0xb8674f67, 0x9033a6c2, 0x6654c6fe, 0x902cbc7e, 0xe4e8aafe, "....." },
  [7641] = { "Grimand Elmoreの仕事", "StormwindのDwarven DistrictにいるGrimand Elmoreと話して下さい。", "パラディンの軍馬も、しかるべき馬鎧がなければただの荷役の獣にすぎません。あなたの軍馬が用いる馬鎧は、ありうる限り最上の素材でできていなければならないだけでなく、事情が事情ですから、霊界と十分に同調していなければなりません。\n\nまず最初にすべきことは、{name}――あなたのbardingを作ることです。StormwindのDwarven Districtには、今生きている中で最も優れた職人の一人、Grimand Elmoreがいます。彼の仕事は安くはありませんが、私たちが求めるのはその質です。彼と話してください。", nil, "やあ――Lord Shadowbreakerから、あんたがこっちへ会いに来ると前もって知らせがあったよ。必要な馬鎧は作ってやるつもりだが、安くも楽でもない。まずそこをはっきりさせておこう。\n\nこれだけは言っておく。Graysonも私がこう言うのを裏付けてくれるだろうが……ここより上等な馬鎧は、Azeroth中どこを探しても見つからないぞ。", 0xaab3e85c, 0x315dc67f, 0x1c01eb68, nil, 0x4be6617c, "...m." },
  [7642] = { "材料集め", "Runecloth 40枚・Arcanite Bar 6本・Arthas' Tear 10本・Stratholme Holy Water vial 5本・金貨150枚を、StormwindのDwarven DistrictにいるGrimand Elmoreに渡して下さい。", "bardingには4つのものが要る――裏地にはrunecloth、板金にはarcanite bars、霊的な同調にはArthas' Tears、霊的な力を吹き込むにはStratholme holy waterだ。実のところ、要るものは5つだな……わしの手間賃の金だ。その手間賃には、すべての作業に加えて手作りの鞍と鐙も含まれとる。\n\nそれが全部揃えば、お前さんのbardingを仕上げられる。それまでの間、お前さんが品物を集めてくる間に、先に取りかかっておけることもいくつかあるぞ。", "ああ、{class}。私が言った品々がなければ、あなたの馬鎧は仕上げられません。全部揃いましたか？", "これは……いや、まさに私が必要としていたものだ。あんたはずいぶん機転の利く{class}じゃないか。\n\nよし、それじゃあこの馬鎧を仕上げてしまおう!", 0x85fed7c1, 0x0cb21e13, 0x5cd28c73, 0xd90f59be, 0x77fdc05e, "....." },
  [7643] = { "Ancient Equine Spirit", "霊馬に与える特別な馬の飼料を手に入れる。SouthshoreのMerideth Carlsonがその飼料の入手先らしい。\n\nFeralasのダンジョン、Dire Maulへ行き、Tendris Warpwoodを倒す。そうすればAncient Equine Spiritが解放される。特別な飼料を与えて霊をなだめる。最後に、Arcanite Bardingを渡して祝福してもらって下さい。", "あなたのbardingには特別な祝福が必要です。ふさわしい霊から授かる祝福です。Dire Maulにそのような霊、Ancient Equine Spiritがいます。今は堕落したtreant、Tendris Warpwoodに囚われています。この忌まわしい獣に裁きを下してください、{name}。\n\n心得ておいてください――解き放つだけでは足りません。祝福を受ける前に、霊を鎮めなければならないのです。それには特別な馬の飼料が要ります。まずSouthshoreへ行き、このことについてMerideth Carlsonと話してください……そして、さらなる犠牲に備えてください。", "Ancient Equine Spiritは、あなたに何かを求めているかのように、期待を込めてあなたを見つめている。", "Ancient Equine SpiritはManna-Enriched Horse Feedの捧げ物を受け取り、木箱に鼻を押しつけると自分で麦と穀物を食べた。少し食べた後、馬はあなたが持っている装甲を見て、装甲を背に乗せるよう求めているかのように体勢を整えた。", 0xf903562c, 0x1c7e0042, 0x6827a6fe, 0x0088376a, 0x73dc7526, "....." },
  [7644] = { "Blessed Arcanite Barding", "Blessed Arcanite BardingをStormwindのCathedral DistrictにいるLord Grayson Shadowbreakerのところへ持ち帰って下さい。", "bardingがAncient Equine Spiritの背に置かれると、それはほのかに光を放つ。一瞬、あたりの空気が力で満ち、次の瞬間にはbardingは馬の背から消え、今はあなたの背負い袋の中に収まっている。\n\nbardingは祝福を受けたようだ。Lord Shadowbreakerの指示どおり、これを持ってStormwindの彼のもとへ戻るべきだろう。", "{name}、戻ったのね！ Merideth CarlsonとTendris Warpwoodの件はうまく片付けられた？ 正直なところ、時々どちらがより大きな脅威なのか分からなくなるわ……", "よくぞここまで来た、我が友よ。そなたの馬鎧は、いよいよ最後の務めに向けてふさわしく整えられた。\n\n贖いの務めが果たされたなら、この馬鎧を用いて軍馬を御することになる。だがその前に、乗り越えるべき途方もない戦いが待っている。そなたの時は近い――さあ来い!\n\nこれを始める前に、もう一つ作らねばならぬ品がある、{name}。馬鎧を作ってもらってから、そなたの機転が失われていないとよいのだが……", 0xcd7cadda, 0xe2bdf073, 0x47656e16, 0x3b0ca232, 0x5f823dd1, "....." },
  [7645] = { "Manna-Enriched Horse Feed", "Hillsbrad Foothills、SouthshoreのMerideth Carlsonのために、Manna-Enriched Horse Feedを作る鍵となる材料、Enriched Manna Biscuitsを$N1個手に入れて下さい。このビスケットを扱っているのはArgent Dawnだけだと知られている。\n\n彼女の機嫌を直すため、$N2ゴールドも渡す必要があります。", "Silver Handの連中は、霊の馬を養える特別な馬の飼料を作れると言った私を狂っていると思ったのさ。誰もが私を狂っていると思った！さあ、今こそ仕返しの時だ！\n\nお前の要るものは作ってやろう、パラディンさんよ……いわゆるチャンピオンさんよ……だが、代償はいただく。この配合には特別なbiscuitsが要る――Argent Dawnだけが売っているEnriched Manna Biscuitsだ。それに私が耐え忍んできた惨めさの償いとして、金も要求する。そう、要求するのだ！\n\nお前がさんざん吹聴している犠牲とやらを見せてみろ、パラディン。", "ほら、これであなたが間違っていたと証明しただろう？ 皆が間違っていたと証明してやったんだ！ ずっと正しかったのは私なんだ！！！", "そうだ、さあ誰が――待て――金までくれるというのか? 俺を気違い呼ばわりしたのはあんたじゃない(実際やつらは俺をいかれた変人と呼んだ)……それでもあんたは、自分が犯してもいない過ちのためにさえ犠牲を払おうというのか?\n\n俺は……俺はあんたを見誤っていた、{name}。もっとhorse feedが要るなら、俺のところへ来い。ただでやる。ありがとう……気高い{class}よ。\n\nだが金はもらっておくぞ――財産を手放すほどいかれてはいないからな。", 0x1f21fe01, 0x0d109102, 0x9d18fe77, 0x76c3ccbb, 0xb4ce0e54, "....." },
  [7646] = { "Divination Scryer", "StormwindのCathedral DistrictにいるLord Grayson Shadowbreakerに、Azerothian Diamond・Pristine Black Diamondを渡して下さい。", "今度はDivination Scryerを組み立てなければなりません。これが、倒れた軍馬を贖う試練の始まりとなります。実は、あなたのscryerはほとんど出来上がっています。Terrordaleで使ったexorcism censerがその触媒となり、私が装置にふさわしい外装をこしらえましょう。\n\nですが、最後に必要な部品は2つのdiamondsです。その輝きも目的も対照的なものでなければなりません――AzerothianとPristine Blackです。この2つが、scryerが闇を貫くための道しるべとなるのです！", "あなたは本当に遠くまで来ましたね、{name}。俗世の品を捧げるこの最後の行いが、あなたの最も偉大な功績の一つの始まりとなるでしょう。私の存在の奥底でそれを感じるのです！", "これらは見事な標本だ、{name}――これで最後の欠片が揃った。ついに、そなたの時が来た!\n\nScholomanceのGreat Ossuaryの奥深くには、数多の者どもの骸が横たわっている。その中に、かつては気高かった軍馬がいる。この軍馬のうつろな魂は今、Death Knight Darkreaverの乗騎として仕えている。そなたが相対するのはその者であり、そなたが裁きを下すのはこの乗騎だ。その魂を贖い、隷属の苦しみから救い出せるのは、{name}、そなただけなのだ。", 0x97882862, 0x21b1c1d8, 0xa1bffac1, 0x377927dd, 0x1b514838, "....." },
  [7647] = { "審判と救済", "ScholomanceにあるGreat Ossuaryの地下の中心でDivination Scryerを使う。そうすれば、あなたが裁かなければならない霊たちが現れる。その霊たちを倒すとDeath Knight Darkreaverが呼び出される。彼を倒し、倒れた軍馬の失われた魂を取り戻す。\n\nCharger's Redeemed SoulとBlessed Enchanted BardingをDarkreaver's Fallen Chargerに渡して下さい。", "この鞄を持って行きなさい――中にはあなたの務めに必要な品が入っています。\n\nGreat Ossuaryの地下室の中心でdivination scryerを使い、裁かれるべき呪われた霊たちを呼び出しなさい。この試練では裁きを賢く使うのです――あなたが思う以上の力を発揮するでしょう。霊たちの後にはデスナイトが現れます。彼を倒し、軍馬の失われた魂を取り戻しなさい。そうして初めて、{name}、あなたはそれを贖い、新たな乗騎にbardingを掛けることができるのです！\n\n幸運を！", "倒れた軍馬の霊が、悲しげな眼差しであなたを見つめている。すべての希望を失ったかのような、悲しく、ほとんど虚ろな瞳であなたを見ている。", "裁きを受けたその魂を返してやると、長らくこの哀れな獣から失われていた生命の輝きが、その瞳に宿る。軍馬が贖われたと裁きを下したうえで馬鎧をその背に載せると、聖なる力の奔流が身の周りに湧き上がるのを感じる。過去の重荷が獣から取り除かれ、軍馬はあなたの手に鼻先をすり寄せる。必要が生じたときには、この獣を自らの乗騎として呼び出せるように、今や感じられる。\n\nあなたは己の壮麗な軍馬を手に入れた、{class}! おめでとう!", 0x46dcb4ff, 0x720120e9, 0x050b5849, 0x6ef6d085, 0x1d80ecd4, "....." },
  [7648] = { "Grimandの最高傑作", "Lord Grayson Shadowbreakerに見てもらうため、StormwindのCathedral Districtにいる彼のところへArcanite Bardingを持って行って下さい。", "<Grimandは額の汗をぬぐい、誇らしげに顔を輝かせる。>\n\nさあできたぞ、友よ。わしの最高の仕事の一つだ――Lord Shadowbreakerが自分の軍馬を求めに行った時に、わしが自ら作ってやったbardingにも劣らん出来だ。最高のものを任せてくれたお前さんの信頼に感謝するよ。\n\nきっとGraysonも自分の目でこの仕事を見たがるだろう。bardingを彼のところへ持っていって、誠実な商いへのわしの礼を伝えてくれ。", "順調に進んでいますね、{name}。bardingを作り終えれば、次の務めへの道は大きく開けるでしょう。", "実に見事な仕事です。Grimandは歳を重ねるほど、腕を上げ続けているようですね。昔、彼が私の馬鎧を作ってくれた頃には、すでにどこを探してもそうはない最高の出来だったのですから、大したものです。\n\nこのbardingは普通の馬なら申し分のない装備となるでしょうが、私たちが相手にしているのはそのような平凡な獣ではありません。{class}の軍馬にふさわしいものとするには、しかるべき存在にこのbardingを祝福してもらう必要があります。それまでは私が預かっておきましょう。", 0xc224bd2c, 0x080a2e44, 0xe90e8178, 0x7eeec2ce, 0xe0f17de5, "....." },
  [7649] = { "Enchanted Thorium Platemail: 第一巻", "本を本来の持ち主に返して下さい。", "この書物にはAthenaeumの印がある。", "書物を取り戻したのだな！", "よくやったな、若いの。\n\n<Lorekeeper Lydrosが本から一ページを引き裂く。>\n\nこのレシピをきっと役立てられるだろう。", 0x3ac91124, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x381b7184, "....." },
  [7650] = { "Enchanted Thorium Platemail: 第二巻", "本を本来の持ち主に返して下さい。", "この書物にはAthenaeumの印がある。", "書物を取り戻したのだな！", "よくやったな、若いの。\n\n<Lorekeeper Lydrosが本から一ページを引き裂く。>\n\nこのレシピをきっと役立てられるだろう。", 0x14e3c64b, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x381b7184, "....." },
  [7651] = { "Enchanted Thorium Platemail: 第三巻", "本を本来の持ち主に返して下さい。", "この書物にはAthenaeumの印がある。", "書物を取り戻したのだな！", "よくやったな、若いの。\n\n<Lorekeeper Lydrosが本から一ページを引き裂く。>\n\nこのレシピをきっと役立てられるだろう。", 0xb08e78dc, 0xdeb95520, 0x10e08c8e, 0xd98d4887, 0x381b7184, "....." },
  [7652] = { "青光の掘り出し物", nil, nil, nil, "よう、旦那、いい話があるんだ。\n\nこのImperial plate armorのレシピをいくつか手放したくてな、引き受けてくれる相手を探してるんだ。代わりに欲しいのはthorium barsだけさ。どうだい?", 0x2ebc19cb, nil, nil, nil, 0xb746ed6b, ".mmm." },
  [7653] = { "Imperial Plate Belt", nil, nil, "ベルトの設計図には、ソリウムの延べ棒が20本必要だな。", "あんたと商売ができて何よりだ。\n\nそれと{name}、その嫌そうな顔はやめてくれよ。", 0xc0c8edee, nil, nil, 0x32c34c39, 0xdea64556, ".mm.." },
  [7654] = { "Imperial Plate Boots", nil, nil, "ブーツの設計図には、ソリウムの延べ棒が40本必要だな。そうとも、40本だ。泣くのか？ ハンカチでも要るか？\n\n<Derotainが笑う。>", "あんたと商売ができて何よりだ。\n\nそれと{name}、その嫌そうな顔はやめてくれよ。", 0xa8299450, nil, nil, 0x8040fdb8, 0xdea64556, ".mm.." },
  [7655] = { "Imperial Plate Bracer", nil, nil, "腕当ての設計図には、ソリウムの延べ棒が20本必要だな。\n\n大丈夫か、坊や？ 顔が真っ赤になってきとるぞ。", "あんたと商売ができて何よりだ。\n\nそれと{name}、その嫌そうな顔はやめてくれよ。", 0x400b50c6, nil, nil, 0xd88eb51a, 0xdea64556, ".mm.." },
  [7656] = { "Imperial Plate Chest", nil, nil, "胸当ての設計図には、thorium barが60本必要だ。\n\nおやおや、またそれか。青いGodsのところへ駆け込んで、なぜ自分を見放したのかと聞くつもりかね? 気をしっかり持て、Nancy! 人生が公平だなどと誰も言っちゃいない。", "あんたと商売ができて何よりだ。\n\nそれと{name}、その嫌そうな顔はやめてくれよ。", 0xb8c48c88, nil, nil, 0xeb58fce6, 0xdea64556, ".mm.." },
  [7657] = { "Imperial Plate Helm", nil, nil, "ソリウムの延べ棒を50本渡しさえすれば、兜の設計図はお前さんのものだ。", "あんたと商売ができて何よりだ。\n\nそれと{name}、その嫌そうな顔はやめてくれよ。", 0xc196bf89, nil, nil, 0xcb20090a, 0xdea64556, ".mm.." },
  [7658] = { "Imperial Plate Leggings", nil, nil, "ソリウムの延べ棒を60本渡しさえすれば、脚防具の設計図はお前さんのものだ。\n\n分かっとる、分かっとる、わしのせいで破産しそうなんだろう！ そんな話は聞き飽きとるから、泣き言はしまっておけ、弱虫め。", "あんたと商売ができて何よりだ。\n\nそれと{name}、その嫌そうな顔はやめてくれよ。", 0xdfbf0203, nil, nil, 0xbb263d48, 0xdea64556, ".mm.." },
  [7659] = { "Imperial Plate Shoulders", nil, nil, "肩当ての設計図には、ソリウムの延べ棒が20本必要だな。", "あんたと商売ができて何よりだ。\n\nそれと{name}、その嫌そうな顔はやめてくれよ。", 0x58cf3eb5, nil, nil, 0x48278a6f, 0xdea64556, ".mm.." },
  [7667] = { "素材援助", "OrgrimmarのValley of WisdomにいるSagorne Crestriderの手伝いに興味があるのであれば、彼にAzerothian DiamondとPristine Black Diamondを渡して下さい。", "{name}、差し迫った問題があって、あなたに助けてもらえないかと思っているのです……物の面でも、心の面でも。説明させてください。\n\nLordaeronのScholomanceの奥深くに、Great Ossuaryと呼ばれる部屋があります。この恐ろしい部屋の闇を貫く装置を完成させなければなりません。始めたことをやり遂げるには、2つのdiamondsが必要です。AzerothianとPristine Blackです。簡単に手に入る品ではないことは分かっています――ただ、私自身にはその資金がないのです。\n\nそれぞれ1つずつ用意していただけませんか？", "物をお願いするのは気が引けるのですが、私が完成させたいと願っている装置、占術の水晶器には、それぞれ一つずつが必要なのです。お手伝いいただけなくても、もちろん分かりますよ。", "そなたの寛大さは比類ない、{name}。その厚意に感謝する。\n\nこれでdivination scryerを仕上げられる。それに、これ以上diamondsを必要とせずに、もっと作れるようになるはずだ……その使い道で私を手伝うことに興味はないか? 極めて重要な務めのためだ、それは請け合う……放っておけば、霊の領域に計り知れぬ災いをもたらしかねぬ務めなのだ!", 0x2664d220, 0x5802fb11, 0xd94f2e58, 0x7d7fce4f, 0xdff68b8a, "....." },
  [7668] = { "Darkreaverの脅威", "ScholomanceにあるGreat Ossuaryの地下の中心でDivination Scryerを使う。そうすれば、あなたが戦わなければならない霊たちが現れる。その霊たちを倒すとDeath Knight Darkreaverが呼び出されるので、彼を倒す。\n\nDarkreaver's HeadをOrgrimmar、Valley of WisdomのSagorne Creststriderのところへ持って行って下さい。", "Death Knight DarkreaverはScholomanceのGreat Ossuaryを支配している。奴は霊界を捻じ曲げて意のままにしようとしており、止めねばならん！ここで、君が作るのを手伝ってくれたscryerの出番だ。\n\nGreat Ossuaryの地下室の中心でdivination scryerを使い、Darkreaverの霊の手下どもを呼び出せ。霊どもを倒せば、デスナイト本人が姿を現す。{name}、奴の首を持ってこい！奴が滅びて初めて、霊界に与えられた損害を元に戻せるのだ！", "一刻を争うのです、{name}。Death Knight Darkreaverの脅威を食い止めることはできましたか？", "これは噛みしめるべき勝利です、{name}! Darkreaverの死によって、霊界をつなぎとめる脆い枷が元に戻るはずです。\n\n報酬も見返りも考えていなかったのに、あなたは求められた以上のことを成し遂げてくれました。あなたは真に価値ある{class}です、友よ。\n\n霊界を守るために行動すること自体が十分な礼になるとは分かっていますが、どうか――感謝を込めて、このささやかな贈り物を受け取ってください。", 0xf4f3bcea, 0x03ae7ce9, 0x5b13350d, 0xc513241d, 0x44e1ce14, "....." },
  [7670] = { "Lord Grayson Shadowbreaker", "StormwindのCathedral DistrictにいるLord Grayson Shadowbreakerと話して下さい。", "時が来ました、{name}。あなたがきっと長い間待ち望んでいたもの……あなたの軍馬を手に入れるには何が必要なのか、学ぶ時です。\n\nStormwindのCathedral DistrictにいるLord Grayson Shadowbreakerと話しなさい。パラディンの最も信頼する乗騎にまつわる秘儀だけでなく、あなた自身の乗騎を得るために待ち受ける務めについても、彼が導いてくれるでしょう。\n\nこの試練でのあなたの幸運を祈ります。光のために、気高き同胞よ！", nil, "会えて嬉しく思う、{name}。そなたが自らの軍馬を得る方法についての知らせを待っていたことは承知している。そして今、その時が来た。\n\nそなたは必ずや、さまざまな形で試されるだろう。だが何よりも試されるのは、目の前に突きつけられる数々の障害を乗り越えようとする意志だ。これらは学びの稽古として課されるものではない。そなたの器はもはや、単なる教育のための試験を超えている。そなたは、生涯を懸けて戦ってきたあの邪悪の手から、未来の相棒を救い出さねばならぬ。\n\n心せよ。そなたの時が来たのだ!", 0x74c8e64a, 0x3b1a14c9, 0x57e25d3f, nil, 0xa28a3953, "...m.", nil, nil, 0x4f89b0e5, nil, nil },
  [7681] = { "ハンターのテストクエスト", "ペットに餌を与えてから、クエストをくれた相手と話して下さい。", "ペットにfeed petを使ってください。", nil, nil, 0x746b49f4, 0x2f058422, 0x34b38a3e, nil, nil, "...mm" },
  [7682] = { nil, "ペットに餌を与えてから、クエストをくれた相手と話して下さい。", "ペットにfeed petを使ってください。", nil, nil, nil, 0x2f058422, 0x34b38a3e, nil, nil, "m..mm" },
  [7701] = { "指名手配：Overseer Maltorius", "Searing GorgeのCauldronにあるSlag Pitの奥深くに、Overseer Maltoriusという名の裏切り者のDark Ironのドワーフがいる。\n\nOverseer Maltoriusを倒して首を取る。報酬を受け取るため、その首をSearing GorgeのLookout Captain Lolo Longstrikerのところへ持って行って下さい。", "Overseer Oilfist閣下の命により、Thorium Brotherhoodの裏切り者の手先にして、新たにCauldronのDark IronのSlag Pit部隊の指揮官に雇われたOverseer Maltoriusを殺し、その首を証として持ち帰ること。\n\nこの賞金の報酬についてはLookout Captan Lolo Longstrikerに会うこと。", "見てわかんねぇのか、いしょがしいんだよ？ なん*ヒック*の用だってんだ？ *ヒック*", "このブサイクなツラをまた拝むことになりゅとは思わなかったじぇ!\n\nこいちゅ、残りの体がくっちゅいてない方がむしろマシに見えりゅな。\n\nほれ、報酬だ*ひっく*、{race}。", 0x03010d28, 0x0202bf14, 0xa7a8fb6a, 0xf201932b, 0x5c34de3e, "....." },
  [7703] = { "Gordok族の未完の仕事", "Gauntlet of Gordok Mightを見つけ、Dire MaulのCaptain Kromcrushのところへ持ち帰って下さい。\n\nKromcrushによれば、「昔々の話」では、王子を名乗る「気味の悪い」エルフ、TortheldrinがGordokの王の一人からそれを盗んだという。", "今はお前が王。だから、自分を王子って呼ぶ気味悪いエルフから、大事なGordokの宝を取り戻せるかも!お前の前の王は失敗した。気味悪いエルフのTortheldrinが昔のGordokの王から盗んでから、ほかの王たちもみんな失敗した!\n\n宝の名前はGauntlet of Gordok Might。昔話では、Gordokのただ一人の真の王だけが取り戻せるって言う。昔話では、気味悪いエルフはまだこのあたりにいるとも言う――お前が見つけたら、ずっとはめていられる強い篭手になる!ヤー、見せてやる!", "ハッ、見つからない、だろ、ボス？ 昔の話、たぶん嘘の話……あの気味悪いエルフ、Gordok kingから盗めるなんて、信じられない！", "おお……お前、本当の王だ! こんなgauntlet、生きてるうちに見られるなんて思わなかった! もうmojoは残ってないみたいだ……たぶんあの気味悪いエルフがgauntletを壊そうとしたんだ。ふん、そいつにはHAR HARと言ってやる!\n\n見ろ――gauntletについたこの印、古い古い、うんと古い時代の魔法の印だ、Gordokより古いってみんな言うぞ。まあ、Gordokの隊長として、おれたちはみんな一つのことを何度も何度も習うんだ――印を生き返らせて、gauntletに力を戻す方法をな!\n\nお前のためにやってやる、王よ! ほら、gauntletを取って、永遠に治めるんだ!", 0xd84c3631, 0xbc347604, 0x302edb3f, 0x238a10a1, 0x67a5cc2d, ".....", nil, nil, nil, nil, 0x01f9cd5f },
  [7704] = { "見ろよ、この大きさ！", "Chambermaid Pillaclencher's PillowをSearing GorgeのEvonice Sootsmokerのところへ持って行って下さい。", "おやおやおや……こいつは驚いた。客室係がとんでもなく大きな飾り立てた枕を持ってたんだが、今やそいつはあんたのものだ。Evonice Sootsmokerなら、この品に薄汚い小さな手でべたべた触りたがるに決まってる。彼女のところへ持っていって、骨折り賃に何かいいものをくれるか見てみな。", nil, nil, 0x446e8ded, 0xd6d832a4, 0xe1b953bc, nil, nil, "...mm" },
  [7721] = { "攻撃用燃料", "FeralasのForgotten Coast沿いにいるSea ElementalとSea SprayからWater Elemental Core 10個を集め、桟橋付近にいるZorbin Fandazzleのところへ持ち帰って下さい。", "自分の良識に逆らってForgotten Coast沿いでエンジニアリングの店を続けるなら、この厄介なエレメンタルどもを何とかしなきゃならん。野放しのエレメンタルの力なんぞ呪われちまえ、ってんだ！\n\n幸いなことに俺にとって、そして今や俺の期待の工作員であるお前にとってもな、エレメンタルどもはUltra-Shrinkerの改良にもってこいの生の力の源なんだ。奴らにたっぷりお仕置きしてやれ！ただしその時は、water elemental coresを必ず取っといてくれよ！", "elemental coresの有用性について技術的な詳細を語って退屈させることもできるが、その代わりに、この重要な任務を果たしてくれたら価値ある硬貨と賞品を差し上げるということで、完遂へと誘うことにしよう。さてさて、もう終わったかね?", "最高にすんばらしい! このcoresがあれば、しばらくは仕事に困らない。おまけに海岸沿いのelementalsも減ったとなれば、考えうる限り最悪の場所に店を構えてしまったと嘆いて泣き寝入りすることも、もうなくなるかもしれない!\n\n私のために骨を折ってくれてありがとう、{name}。こうするのは確かに懐に痛いが、あなたにも分かって喜んでもらえそうな感謝の示し方をさせてくれ……戦利品だ!", 0x809826c8, 0x3172fbce, 0x2e6a8654, 0x00a49bad, 0x0d4b34c8, "....." },
  [7722] = { "フラックスって何だ？", "Slag Pit of the Cauldronのどこかに、Overseer Maltoriusが盗んだSecret Plans: Fiery Fluxがある。その設計図を見つけ、Searing GorgeのMaster Smith Burninateのところへ持って帰って下さい。", "あのろくでなしのMaltoriusが一族を抜けた時、奴は汚れ一つない秘術の水晶よりも価値のあるものを持ち去った。我らのfiery fluxのレシピだ！賭けてもいいが、あのレシピはDark Ironsの間での奴の新たな昇進の取引の一部だったに違いない。\n\n我らの秘密の製法を取り戻してほしい、{name}。Slag Pitの奥深く、Maltoriusの近くのどこかにあるはずだ。", "設計図は見つかったか?", "奴の歯も蹴り折ってやったんだろうな、{name}。Ragnarosに誓って、奴にはそれがお似合いだ。\n\nさて、本題に入ろうか。", 0xc07aa3bb, 0x8f132878, 0x336636d3, 0x85bbae45, 0x27d3986a, "....." },
  [7723] = { "この太い指め", "Hansel Heavyhandsは、Heavy War Golemsを$N1体倒してほしいと言っています。\n\nHeavy War GolemsはSearing GorgeのCauldron周辺をうろついている。十分な数を倒したら、Searing GorgeのHanselのところへ戻って下さい。", "残念ながら、このぶっとい指のせいで、前みたいに殴りつけることができねえんだ。ほれ、ここの気候と気圧の低さが合わさって、わしの指が膨れちまうのさ。まるででっかいThelsamar Blood Sausagesみてえだ、ほんとに……\n\nお前さんには、わしの仕事やら何やらを代わりに片付けてもらうことになる。\n\nわしの予定の一つ目：Gorgeのheavy war golemsを、こっぴどくぶちのめすことだ。さっさと取りかかれ。", "あいつらを叩きのめしてきたか?", "お前さんはいい若いのだよ、ほんとに。骨折りの礼に、ちょいとした贈り物を用意したぞ。", 0x1866df92, 0x30f7c955, 0xe5c62f10, 0xcbb0cf9d, 0xcf9f67a7, ".....", nil, nil, nil, nil, 0x53921380 },
  [7724] = { "炎の脅威！", "Hansel Heavyhandsは、Searing GorgeでGreater Lava Spidersを$N1体倒してほしいと言っています。Greater Lava SpidersはSearing Gorgeの台地や溶岩溜まりで見つかる。\n\nGreater Lava Spidersを十分な数倒したら、Searing GorgeのHansel Heavyhandsのところへ戻って下さい。", "まったく、この老いぼれHanselが一息ついて人生を振り返ろうとするたびに、お偉方がまた仕事を寄こしやがる。\n\nわしだって考え事をせにゃならん、勘弁してくれ！わしの言ってること分かるか？勘弁。してくれ。\n\nで、ここのgreater lava spidersが何やら騒ぎを起こしとる。Oilfistが言うには、奴らは……その、ええと、まあとにかく、火を噴くんだと。そういうのは子供らを怖がらせるからな。\n\nというわけで、奴らを殺さにゃならん。いや、お前さんが殺さにゃならんのだ。", "あいつの言ってたことは本当だった? 本当にケツから出てくるの?", "<Hanselはくしゃみをする。>\n\n風邪をひいちまったみてえだ。まったく、このクソ寒い気候め!", 0xe1aa77fc, 0x8d8bb1a0, 0x14a3807c, 0x57ac94ac, 0x18ad5817, "....." },
  [7727] = { "Incendosaurs？Whateverosaurってとこだな", "Hansel Heavyhandsは、Incendosaursを$N1体倒してほしいと言っています。\n\nIncendosaursはSlag Pitの中の溶岩溜まりに棲みついている。Slag PitはSearing GorgeのCauldronにある。\n\nIncendosaursを十分な数倒したら、Searing GorgeのHansel Heavyhandsのところへ戻って下さい。", "足のこぶだよ、若いの。わしの足のこぶにこぶができちまった。足がこんな有様で、どうやって殺しなんかしろってんだ？だからお前さんが手伝うのさ。\n\nScrangeとBurninateから、こいつらを片付けろと命じられてな。そうすりゃSlag Pitの溶岩の池に探検隊を送り込んで調べられるってわけだ。どうやら下じゃincendosaursだか何だかが、あらゆる厄介事を起こしてるらしい。さあ、さっさと行け。incendosaurが絶滅するまで戻ってくるんじゃねえぞ。", "<Hanselは忙しそうに足のこぶをさすっている。>\n\n突っ立ってないで、オイルとヘチマを取ってきて、このこぶをこすってくれ。\n\nヘチマを持ってない? それならだ! そろそろお前さんをヘチマ探しに行かせる頃合いかもしれんな?\n\nおい、どこへ行くんだ?", "ああ、足が痛え。\n\nお前さんがヘチマを持ってなかったもんで……", 0xd4823678, 0xa49a631f, 0xe0116ef8, 0xc2bee4d5, 0x071dfa2a, ".....", nil, nil, 0x64ef711a, nil, nil },
  [7728] = { "盗難：Smithing TuyereとLookout's Spyglass", "Smithing TuyereとLookout's Spyglassを見つけ、Searing GorgeのTaskmaster Scrangeのところへ持って帰って下さい。\n\nこれらの品について分かっているのは次のことだけだ。どちらも間違いなくDark Ironのドワーフに盗まれた。Smithing Tuyereは鍛冶屋が使う鍛冶の道具で、Lookout's Spyglassは見張りにとってかけがえのない監視の道具だ。", "以下の品が盗まれた：\n\n*Dark Iron Tuyereを一つ。\n\n*Lookout's Spyglassを一つ。\n\nこれらの盗品を見つけて返却した者には、報酬が与えられる。\n\nThorium Brotherhoodは、これらの品がSearing Gorgeに住む不届きで嫉妬深いDark Ironのドワーフどもに盗まれたものと確信している。\n\n問題の望遠鏡は見張りにとって優れた道具であり、羽口はかけがえのない鍛冶道具であった。\n\n失われた品を見つけたら、Scrangeのもとへ返却すること。", "報酬目当てで来たんなら、盗まれた品をこっちに渡してもらわないとな。", "素晴らしい仕事だ! では報酬だ。", 0x64a25f02, 0xa792a255, 0xd964ba68, 0x75ecaf91, 0x700453bf, "....." },
  [7729] = { "求人：競争相手の間引き", "Dark Iron Taskmastersを$N1体とDark Iron Slaversを$N2体倒す。任務を果たしたら、Searing GorgeのTaskmaster Scrangeのところへ戻って下さい。", "Taskmaster Scrangeが、Searing Gorgeで「競争相手を間引く」手伝いをしてくれる優秀な男女を数名募集している。\n\nこの職に興味があるなら、Searing Gorgeへ出向き、目に入るDark Iron TaskmasterとDark Iron Slaverをすべて殺すこと。\n\n服が十分に血まみれになったら、Taskmaster Scrangeのもとへ戻ること。\n\n十分に血まみれになれば分かるので、尋ねないこと。", "確かめるために、服を着たままと脱いだ状態で体重を量らないといけないな。", "15.9ポンド! 服についた血と臓物の重さとしては新記録かもしれないぞ! おめでとう、{class}!", 0x27d0f06d, 0xb94548f3, 0x9394b676, 0x765dfe1d, 0xd80310ca, "....." },
  [7730] = { "のさばるZukk'ash", "FeralasのCamp MojacheにいるHadoken Swiftstriderに、Zukk'ash Carapace 20個を渡して下さい。", "これまでの偵察でつかんだところでは、gnollsの南にいる敵は虫のような種族らしい。正直なところ、奴らに知性があるかどうかはどうでもいい。奴らがgnollsを煽って我々に狂ったように襲わせているのなら、奴らはgnollsと同じくらい――いや、それ以上の脅威だ。\n\nZukk'ashの虫どもが棲む場所、Writhing Deepの奥深くへ攻め込め。奴らの数を減らし、見つけたものを私に報告しろ。お前の働きの証として、奴らのcarapacesを持ち帰るのだ。", "狩りの具合はどうだ、{name}? 成功の報告に来たのか?", "よくやった、{class}。Zukk'ashの勢力の広がりは全面的な侵攻でなければ食い止められないが、お前のおかげで適切な戦略を練るだけの時間が稼げた。\n\nこの甲殻は必ず分析させる。残念ながら我々が予想していたよりはるかに大きな問題となってしまったものに対処する前に、奴らについてすべてを知る必要があるからな。", 0x932e3026, 0xb72ef59a, 0x883ce546, 0xc0557a8f, 0x83d0e4be, "....." },
  [7731] = { "Stinglasher", "Writhing DeepにいるStinglasherを倒し、その分泌腺をFeralasのCamp MojacheにいるHadoken Swiftstriderに渡して下さい。", "Writhing Deepを調べていた斥候の一人が、巨大な虫を見たと報告してきた――他に見かけた虫よりずっと大きく、ねじれた地形をうろついていたそうだ。大きいだけでなく、他の虫にはない何らかのオーラを発しているらしい。我々はそいつに名を付けた――Stinglasherだ。\n\nこの新たな脅威への最善の対処法を探る上で、この獣の内臓は研究にかけがえのないものとなる。分泌腺を切り取って、すぐに私のもとへ持ってこい！", "Stinglasherはもう倒せたか?", "見事だ、{class}……実に見事だ! Stinglasherが本当に奴らの最も強い生物の一体であるなら、あの獣の研究はいずれ大いに価値のあるものとなるだろう。それを活かせるだけの間、我々が身を守り抜くようにするのが今の私の務めだ。\n\n野営地全体からの感謝のしるしとして、この懸賞金を受け取ってくれ、{name}。よくやった。", 0x77138744, 0x4fd44652, 0x73c277a8, 0xb18b3f63, 0xe87d41a1, "....." },
  [7732] = { "Zukk'ash報告書", "Camp Mojache Zukk'ash ReportをZilzibin Drumloreに届けて下さい。彼はOrgrimmarのDragに住んでいます。", "Zukk'ashの虫どもがCamp Mojacheにもたらす脅威に、お前は二重によく対処してくれた。こいつらの脅威はまだ終わりには程遠い。Hordeのために、最後にもう一つ務めを頼みたい。\n\nこれはZukk'ashの虫どもについて我々が知り得たすべての情報をまとめた文書だ。これをOrgrimmarのDragにいるZilzibin Drumloreに届けてほしい。奴はこういう異質な生き物の専門家だ。我々が得た知識で何かしてくれることを願っている。", "ようこそ、友よ……急ぎの用があるように見えるな。何か手伝えることはあるか?", "ああ、これを待っていた。あなたが対峙した生き物……あれはHordeが無視し続けることを選んでいる古の脅威だ。Hadokenがこれを、そしてあなたを私のもとへ連れてきたのは賢明だった。\n\nZukk'ashはsilithidと呼ばれる生き物に他ならない。考えのない厄介者にすぎないと思う者もいるだろうが、断言しよう、奴らはAllianceが集められるどんなものよりも、はるかに、はるかに恐ろしい脅威だ。\n\nその気があり、十分な力があるなら、この脅威を明るみに出すためにあなたの助けを借りたい。", 0x5199ec19, 0xdeed09ff, 0x58b47835, 0x78492e92, 0x2c9e366b, "....." },
  [7733] = { "品質の向上", "Rage Scar Yeti Hidesを$N1枚、FeralasのFeathermoon StrongholdにいるPratt McGrubbenのところへ持って行って下さい。", "もっと良いhidesの出どころの手がかりをつかんだんだ。信じられないかもしれないけどな！Feralasの北部――Rage Scar Holdの奥深くに、また別のyetisの群れがいるんだ。前にお前が相手にした奴らよりずっと手強いから、もっと大きな挑戦をする気があるなら、せいぜい油断しないことだな！\n\n奴らのhidesを10枚ひと束持ってきてくれたら、たっぷり礼をするよ。ここへ持ってきてくれ、それで取引は完了だ。", "このRage Scar yeti hidesがFeral Scarのものと同じくらいの品質なら、トリウム並みに頑丈かもしれないぞ!\n\nすごいと思わないか!", "素晴らしい、素晴らしい! これは信じられないほどうまくいくぞ――ちゃんとなめせば、ずっと硬くなるのがもう分かる。\n\n手伝ってくれて改めてありがとう、{name}。ほら――私の最新作をひとつ受け取ってくれ。", 0xa8bb365e, 0xc92407e5, 0x69ee584c, 0xc4178ba9, 0xc3980197, "....." },
  [7734] = { "品質向上", "FeralasのCamp MojacheにいるJangdor Swiftstriderに、Rage Scar Yeti Hide 10枚を渡して下さい。", "もっと良いhidesの出どころの手がかりをつかんだんだ。信じられないかもしれないけどな！Feralasの北部――Rage Scar Holdの奥深くに、また別のyetisの群れがいるんだ。前にお前が相手にした奴らよりずっと手強いから、もっと大きな挑戦をする気があるなら、せいぜい油断しないことだな！\n\n奴らのhidesを10枚ひと束持ってきてくれたら、たっぷり礼をするよ。ここへ持ってきてくれ、それで取引は完了だ。", "このRage Scar yeti hidesがFeral Scarのものと同じくらいの品質なら、トリウム並みに頑丈かもしれないぞ!\n\nすごいと思わないか!", "素晴らしい、実に素晴らしい! これは驚くほどうまくいきそうだ。きちんとなめせばずっと硬くなるのが、もう分かるよ。\n\n助けてくれて改めて礼を言う、{name}。さあ、私の最新の作品の一つを受け取ってくれ。", 0xa8bb365e, 0x8a00501d, 0x69ee584c, 0xc4178ba9, 0xe3079241, "....." },
  [7761] = { "Blackhand's Command", "非常に間抜けなオークです。Orb of Commandに接触するには、Mark of Drakkisathを得て焼印を見つける必要があるようです。\n\nこの手紙は、General Drakkisathが焼印を守っていることを示しています。調べてみた方がよいでしょう。", "大馬鹿め、\n\n部外者が主の住処へ接近するのを阻止するのに、お前の力は実にあてにならん。大方お前は死ぬだろうが、その場合にも、この宝玉そのものにはBlackwingへ部外者が直接転送するのを阻む安全設計がある。\n\n手にMark of Drakkisathを烙印された者のみが宝玉を活用できるのだ。有り難いことに、Drakkisathはお前のような無能者ではない、補給係。あやつは焼印を自分で守っておる!\n\n-Warchief Rend Blackhand\n\n追伸　この手紙は処分しておけ、馬鹿者。", nil, "赤熱した焼印が体に押し当てられても、あなたは怯みませんでした。大した我慢強さです!\n\nこれでMark of Drakkisathが手に入りました。城へ乗り込むのを楽しみましょう。", 0xcc57347c, 0xe176a851, 0xb08323d4, nil, 0x4ec9e05c, "...m." },
  [7781] = { "Blackrock の君主", "Stormwind にいる Highlord Bolvar Fordragon のところへ Head of Nefarian を持ち帰って下さい。", "あの懐かしい感覚が戻ってくる。歓迎すべき勝利の疼きが、全身に響き渡る。目の前には、巨大で戦いの傷跡が刻まれたNefarianの頭がある。それをあなたの大君主のもとへ持ち帰るのだ、勇者よ。", "信じられぬ!", "{name} 、そなたが成し遂げたことの持つ意味は語るまでもあるまい。この日は年代記に記されるであろう。これほどの勝利は長い間 Alliance には伝わっておらん――あったにせよ、滅多に無いことだ!", 0xe644b2ee, 0x4e6be388, 0x5f4dbb3a, 0xfa030e66, 0xaa731d81, "....." },
  [7782] = { "Blackrock の君主", "Stormwind City の Valley of Heroes へ向かい Field Marshal Stonebridge と話して下さい。", "Valley of Heroes へ行き、Field Marshal Stonebridge と話すがよい。", nil, "<Field Marshal Afrasiabi は頭を下げた。>\n\n褒賞をお選び下さい。祝賀を始めさせていただきます!", 0xe644b2ee, 0xf1b8542f, 0xc0f0a1f4, nil, 0x59a2c0b6, "...m." },
  [7783] = { "Blackrockの王", "Head of NefarianをOrgrimmarのThrallに返して下さい。", "懐かしい気持ちが蘇ってきた。体全体に、歓迎すべき勝利の痛みが響き渡っている。あなたの前に横たえられているのは、歴戦を物語る巨大なNefarianの首だ。これをWarchiefに返すのだ、戦士よ。", "そなたがとどめの一撃を放った時、あの獣がどんな顔をしたか、この目で見られればよかったのだがな、{name}。", "{name}、お前は再びHordeに栄誉をもたらしたのだ。Deathwingの子は死んで横たわった。間違いなく、邪悪な者が覚醒している。", 0xe644b2ee, 0x9a97e711, 0x5f012492, 0x32e43d2d, 0xfadf38e5, "....." },
  [7784] = { "Blackrockの王", "OrgrimmarのHigh Overlord Saurfangと話して下さい。彼はValley of Strengthであなたを待ちながら立っています。", "Valley of StrengthにいるHigh Overlord Saurfangを探し出せ。", nil, "皆によく見えるところに私が獣の首を飾れるように、報酬を選んでくれ。", 0xe644b2ee, 0x49c92018, 0x3e5a2c72, nil, 0x5ae91ac1, "...m." },
  [7785] = { "器を調べよ", "Vessel of Rebirth を調べ、Highlord Demitrian のところへ持ち帰って下さい。", "転生の器を調べよ。Windseeker が再び生まれるのはこの中からだ!", "彼を永遠の牢獄から解き放ってくれるか?", "お前が聖戦において守られんことを。主がお前の働きを祝福せんことを。", 0x4d00c480, 0xa77a8d6f, 0xc797dde0, 0xd12827fa, 0x3e738341, "....." },
  [7786] = { "Thunderaan the Windseeker", "Thunderaan the Windseeker を牢から解放するには、Bindings of the Windseeker の右半分と左半分・ Elementium 10本・ Essence of the Firelord を Silithus の Highlord Demitrian に渡さねばなりません。", "知っていることはすべて話したぞ、{name} 。elementium を見つけるのはお前だ。火の王の化身を滅ぼすのはお前だ。\n\n為し遂げて Thunderaan の祝福を得よ。", "必要とあらば、世界を跪かせてしまえ！", "夢でさえこの日を予見しようとはしなかった。\n\n見よ、定命の者。\n\n見よ、何者よりも長く存在せし者を!\n\n見よ、タイタンと神にまみえし者を!\n\n蘇れ、我が主よ! くびきから解き放たれよ!", 0x30d08f81, 0x68665a74, 0xaaceb8e0, 0xb1d1afb9, 0x6900d53f, "....." },
  [7787] = { "蘇れ、Thunderfury!", "Dormant Wind Kissed Blade を Highlord Demitrian に渡して下さい。", "Wind Seeker を倒した。眠りについた剣を手に取り、裏切りのために集めさせられた材料を使って Thunderfury を覚醒するよう、嘘つきの卑劣漢 Demitrian に強制しなくてはならない。", "<Demitrianはあなたの前で身をすくめている。>", "頼む、攻撃しないでくれ! 持って行け! この剣を持って行け! Demitrian に哀れな人生をやり直させてくれ!", 0xecb94e11, 0xe22ca07c, 0x3bc99176, 0x092cd967, 0xece60a9a, "....." },
  [7788] = { "侵略者を打ち破れ！", "Warsong Gulchに入ってHordeを打ち負かし、Warsong Gulch Mark of Honorを手に入れて、Silverwing GroveのSentinel Farsongのところへ戻って下さい。", "このトンネルの先には、争いと混乱の戦場が広がっています、若き{class}よ。Hordeは我らの聖なる森を荒らし続け、戦争の機械を動かすために常緑の木々を切り倒しているのです。\n\nWarsong Gulchに入り、Silverwing Holdを守りなさい。侵攻してくるHordeの軍勢を押し返すのです！\n\nこれを成し遂げ、talisman of meritを手に入れなさい。そのtalismanを私のもとへ持ってくれば、{name}、報酬を与えましょう。", "Warsong Gulchで戦い、Silverwing Holdを守ってきたか?", "お前はWarsong Gulchでの我々の戦いにおいて、その価値を証明した。これからも大義に力を貸し、さらにMarks of Honorを持ってくるのだ。そうすれば、我々の信頼をさらに得られるだろう。", 0x55520e44, 0xfeb46d9a, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [7789] = { "Silverwingの簒奪者の鎮圧", "Warsong Gulchに入ってAllianceを打ち負かし、Warsong Gulch Mark of Honorを手に入れて、Mor'shan Base CampのCaptain Shatterskullのところへ持って行って下さい。", "Ashenvaleの森の荒野は、Hordeの力に屈するのだ、{race}。Silverwingが何を言おうと何をしようと、我らの至上の使命を止めることはできん。KalimdorはHordeのものだ。当然我らのものであるものを刈り取るのを、奴らはよくも邪魔しようとするものだ！\n\n奴らが我らの前進を遅らせようとするひ弱な試みを切り崩しながら、胸に誇りをみなぎらせるがいい。Silverwing Sentinelsを倒し、Warsong mark of honorを手に入れろ。その印を持って戻ってくれば、{name}、報酬を与えよう。", "敵の血こそがmark of honorだ。お前はそのmarkを持っているか?", "<Captain Shatterskullは勝利の雄叫びを上げる>\n\n奴らはあとどれだけ耐えられる? Hordeの手でどれだけのAllianceのクズどもが死ねば、奴らは退くのだ? それは時が教えてくれるだろう、{race}……", 0x636625b4, 0xc94c2293, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [7791] = { "羊毛の寄付", nil, nil, "現在、wool clothの寄付を受け付けています。wool cloth60枚を寄付していただければ、その寛大な行いがStormwindに十分に認められるでしょう。woolの蓄えの状況からすると、あなたからいただくのは合計60枚だけで済みます。残りはこの世界の他の方々から集めて、この運動を支えられるはずです。\n\nwool cloth60枚をお持ちで寄付の準備ができているなら、今すぐお預かりできますよ。", "素晴らしい! 寛大な寄付に感謝します、{name}!", 0xaad71c6f, nil, nil, 0xbfdb39e9, 0xde0116d9, ".mm.." },
  [7792] = { "羊毛の寄付", nil, nil, "現在、wool clothの寄付を受け付けています。wool cloth60枚を寄付していただければ、その寛大な行いがDarnassusに十分に認められるでしょう。woolの蓄えの状況からすると、あなたからいただくのは合計60枚だけで済みます。残りはこの世界の他の方々から集めて、この運動を支えられるはずです。\n\nwool cloth60枚をお持ちで寄付の準備ができているなら、今すぐお預かりできますよ。", "素晴らしい! 寛大な寄付に感謝します、{name}!", 0xaad71c6f, nil, nil, 0x30fa2bb9, 0xde0116d9, ".mm.." },
  [7793] = { "Silkの寄付", nil, nil, "他の多くの布と同じく、silkの在庫も過去最低になっています。蓄えの状況からすると、あなたからいただくのは合計60枚のsilkだけで済みます。残りは他の方々の支援で目標に届くはずです。\n\nそれに、silkのような慈悲深い贈り物は、きっとこの地域でのあなたの評判を高めてくれますよ! silk cloth60枚をお持ちで寄付の準備ができているなら、今すぐお預かりできますよ。", "素晴らしい! 寛大な寄付に感謝します、{name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7794] = { "Mageweaveの寄付", nil, nil, "mageweaveが不足していて、蓄えを補うためにあなたの力を借りたいのです! 地域全体の協力を当てにしているので、目標に届くにはあなたからmageweave cloth60枚を寄付していただくだけで十分です。そのような寛大さをStormwindが見過ごすことはありません、お約束しますよ!\n\nmageweave cloth60枚をお持ちで寄付の準備ができているなら、今すぐお預かりできますよ。", "素晴らしい! 寛大な寄付に感謝します、{name}!", 0x2c4ad0c3, nil, nil, 0x1ff8b690, 0xde0116d9, ".mm.." },
  [7795] = { "Runeclothの寄付", nil, nil, "{name}、あなたは私たちの布集めに多大な貢献をしてくれました。蓄えを補おうと懸命に取り組んでいますが、ひとつだけ依然として極端に足りない布があります。runeclothです。私たちはそれを本当に切実に必要としていて、これまでのようにあなたが力を貸してくれることを願っています!\n\nもしよければ、手放せるだけのruneclothを持ってきてください。まずは60枚の寄付を一度受け付けて、そこから先はまた考えましょう。", "素晴らしい――これはすぐに役立てますよ、約束します。改めてご協力に感謝します! あなたがいなければ、私たちは本当に途方に暮れていたでしょう。\n\nこれだけ寄付をしてくださったのですから、今後もruneclothを寄付していただけるなら、喜んで受け付けます。必ず私に声をかけてください。あなたの善行が見過ごされないよう、私が責任を持って取り計らいます!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7798] = { "Silkの寄付", nil, nil, "他の多くの布と同じく、silkの在庫も過去最低になっています。蓄えの状況からすると、あなたからいただくのは合計60枚のsilkだけで済みます。残りは他の方々の支援で目標に届くはずです。\n\nそれに、silkのような慈悲深い贈り物は、きっとこの地域でのあなたの評判を高めてくれますよ! silk cloth60枚をお持ちで寄付の準備ができているなら、今すぐお預かりできますよ。", "素晴らしい! 寛大な寄付に感謝します、{name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7799] = { "Mageweaveの寄付", nil, nil, "mageweaveが不足していて、蓄えを補うためにあなたの力を借りたいのです! 地域全体の協力を当てにしているので、目標に届くにはあなたからmageweave cloth60枚を寄付していただくだけで十分です。そのような寛大さをDarnassusが見過ごすことはありません、お約束しますよ!\n\nmageweave cloth60枚をお持ちで寄付の準備ができているなら、今すぐお預かりできますよ。", "素晴らしい! 寛大な寄付に感謝します、{name}!", 0x2c4ad0c3, nil, nil, 0x4ff1246f, 0xde0116d9, ".mm.." },
