  [7871] = { "侵略者を打ち破れ！", "Warsong Gulchに入ってHordeを打ち負かし、Warsong Gulch Mark of Honorを手に入れて、Silverwing GroveのSentinel Farsongのところへ戻って下さい。", "このトンネルの先には、争いと混乱の戦場が広がっています、若き{class}よ。Hordeは我らの聖なる森を荒らし続け、戦争の機械を動かすために常緑の木々を切り倒しているのです。\n\nWarsong Gulchに入り、Silverwing Holdを守りなさい。侵攻してくるHordeの軍勢を押し返すのです！\n\nこれを成し遂げ、Mark of Honorを手に入れなさい。それを私のもとへ持ってくれば、{name}、報酬を与えましょう。", "Warsong Gulchで戦い、Silverwing Holdを守ってきたか?", "お前はWarsong Gulchでの我々の戦いにおいて、その価値を証明した。これからも大義に力を貸し、さらにMarks of Honorを持ってくるのだ。そうすれば、我々の信頼をさらに得られるだろう。", 0x55520e44, 0xfeb46d9a, 0x682b535e, 0x71ff749c, 0xf9915c4e, "....." },
  [7872] = { "侵略者を打ち破れ！", "Warsong Gulchに入ってHordeを打ち負かし、Warsong Gulch Mark of Honorを手に入れて、Silverwing GroveのSentinel Farsongのところへ戻って下さい。", "このトンネルの先には、争いと混乱の戦場が広がっています、若き{class}よ。Hordeは我らの聖なる森を荒らし続け、戦争の機械を動かすために常緑の木々を切り倒しているのです。\n\nWarsong Gulchに入り、Silverwing Holdを守りなさい。侵攻してくるHordeの軍勢を押し返すのです！\n\nこれを成し遂げ、Mark of Honorを手に入れなさい。それを私のもとへ持ってくれば、{name}、報酬を与えましょう。", "Warsong Gulchで戦い、Silverwing Holdを守ってきたか?", "お前はWarsong Gulchでの我々の戦いにおいて、その価値を証明した。これからも大義に力を貸し、さらにMarks of Honorを持ってくるのだ。そうすれば、我々の信頼をさらに得られるだろう。", 0x55520e44, 0xfeb46d9a, 0x682b535e, 0x71ff749c, 0xf9915c4e, "....." },
  [7873] = { "侵略者を打ち破れ！", "Warsong Gulchに入ってHordeを打ち負かし、Warsong Gulch Mark of Honorを手に入れて、Silverwing GroveのSentinel Farsongのところへ戻って下さい。", "このトンネルの先には、争いと混乱の戦場が広がっています、若き{class}よ。Hordeは我らの聖なる森を荒らし続け、戦争の機械を動かすために常緑の木々を切り倒しているのです。\n\nWarsong Gulchに入り、Silverwing Holdを守りなさい。侵攻してくるHordeの軍勢を押し返すのです！\n\nこれを成し遂げ、Mark of Honorを手に入れなさい。それを私のもとへ持ってくれば、{name}、報酬を与えましょう。", "Warsong Gulchで戦い、Silverwing Holdを守ってきたか?", "お前はWarsong Gulchでの我々の戦いにおいて、その価値を証明した。これからも大義に力を貸し、さらにMarks of Honorを持ってくるのだ。そうすれば、我々の信頼をさらに得られるだろう。", 0x55520e44, 0xfeb46d9a, 0x682b535e, 0x71ff749c, 0xf9915c4e, "....." },
  [7874] = { "Silverwingの簒奪者の鎮圧", "Warsong Gulchに入ってAllianceを打ち負かし、Warsong Gulch Mark of Honorを手に入れて、Mor'shan Base CampのCaptain Shatterskullのところへ持って行って下さい。", "Ashenvaleの森の荒野は、Hordeの力に屈するのだ、{race}。Silverwingが何を言おうと何をしようと、我らの至上の使命を止めることはできん。KalimdorはHordeのものだ。当然我らのものであるものを刈り取るのを、奴らはよくも邪魔しようとするものだ！\n\n奴らが我らの前進を遅らせようとするひ弱な試みを切り崩しながら、胸に誇りをみなぎらせるがいい。Silverwing Sentinelsを倒し、Mark of Honorを手に入れろ。そのMarkを持って戻ってくれば、{name}、報酬を与えよう。", "敵の血こそがmark of honorだ。お前はそのmarkを持っているか?", "<Captain Shatterskullは勝利の雄叫びを上げる>\n\n奴らはあとどれだけ耐えられる? Hordeの手でどれだけのAllianceのクズどもが死ねば、奴らは退くのだ? それは時が教えてくれるだろう、{race}……", 0x636625b4, 0xc94c2293, 0x2eb6b1fd, 0xd1cff4b7, 0x160777a5, "....." },
  [7875] = { "Silverwingの簒奪者の鎮圧", "Warsong Gulchに入ってAllianceを打ち負かし、Warsong Mark of Honorを手に入れて、Mor'shan Base CampのCaptain Shatterskullのところへ持って行って下さい。", "Ashenvaleの森の荒野は、Hordeの力に屈するのだ、{race}。Silverwingが何を言おうと何をしようと、我らの至上の使命を止めることはできん。KalimdorはHordeのものだ。当然我らのものであるものを刈り取るのを、奴らはよくも邪魔しようとするものだ！\n\n奴らが我らの前進を遅らせようとするひ弱な試みを切り崩しながら、胸に誇りをみなぎらせるがいい。Silverwing Sentinelsを倒し、Warsong mark of honorを手に入れろ。その印を持って戻ってくれば、{name}、報酬を与えよう。", "敵の血こそがmark of honorだ。お前はそのmarkを持っているか?", "<Captain Shatterskullは勝利の雄叫びを上げる>\n\n奴らはあとどれだけ耐えられる? Hordeの手でどれだけのAllianceのクズどもが死ねば、奴らは退くのだ? それは時が教えてくれるだろう、{race}……", 0x636625b4, 0x3df29510, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [7876] = { "Silverwingの簒奪者の鎮圧", "Warsong Gulchに入ってAllianceを打ち負かし、Warsong Gulch Mark of Honorを手に入れて、Mor'shan Base CampのCaptain Shatterskullのところへ持って行って下さい。", "Ashenvaleの森の荒野は、Hordeの力に屈するのだ、{race}。Silverwingが何を言おうと何をしようと、我らの至上の使命を止めることはできん。KalimdorはHordeのものだ。当然我らのものであるものを刈り取るのを、奴らはよくも邪魔しようとするものだ！\n\n奴らが我らの前進を遅らせようとするひ弱な試みを切り崩しながら、胸に誇りをみなぎらせるがいい。Silverwing Sentinelsを倒し、Mark of Honorを手に入れろ。そのMarkを持って戻ってくれば、{name}、報酬を与えよう。", "敵の血こそがmark of honorだ。お前はそのmarkを持っているか?", "<Captain Shatterskullは勝利の雄叫びを上げる>\n\n奴らはあとどれだけ耐えられる? Hordeの手でどれだけのAllianceのクズどもが死ねば、奴らは退くのだ? それは時が教えてくれるだろう、{race}……", 0x636625b4, 0xc94c2293, 0x2eb6b1fd, 0xd1cff4b7, 0x160777a5, "....." },
  [7877] = { "Shen'dralarの財宝", "Athenaeumへ戻り、Treasure of the Shen'dralarを見つけて下さい。報酬を手にするのです!", "書庫Athenaeumで、階段の下に隠された古い木箱が見つかるはずです。そこからどれか好きなものを持っておいきなさい。", nil, "あなたは木箱を開けた……。", 0xe29bd883, 0x031a4aa1, 0x4ca8e2d2, nil, 0x549f5efb, "...m." },
  [7905] = { "Darkmoon Faire", "Free Ticket Voucher を Gelvas Grimgate に届けて下さい。彼は Darkmoon Faire carnival の場所にいます。", "Darkmoon Faire がやって来たよ! Darkmoon Faire が町へ来たら、そのすべての不思議と熱狂を体験していってくれ!\n\n今すぐやるなら、この引換証を無料の賞品チケットに交換できるよ! 祭り会場にいる Gelvas Grimgate に引換証を持って行くだけだ。\n\nちょうど今、Darkmoon Faire は Elwynn Forest の Goldshire のすぐ外でやってるよ。この機会を逃すなよ! 今日行くんだ!", "はい、友よ、何かご用ですか? 引き換えが必要なvoucherをお持ちですか?", "Darkmoon Faire へようこそ! この引換証は5枚分だね、はいよ、チケット5枚だよ!\n\nチケットを貯めたら、貴重な賞品と引き替えるにはオレに話しかけるんだぞ。もっとチケットを手に入れれば、もっと賞品が獲得できるんだ。頑張れよ!", 0x81e45326, 0x59d160bd, 0xb2786af9, 0x08ce32b9, 0xf62b21ee, "....." },
  [7906] = { "Darkmoonカード - 獣", nil, nil, nil, nil, 0x73dd5b02, nil, nil, nil, nil, ".mmmm" },
  [7907] = { "Darkmoon Beast Deck", "Darkmoon Faireが町へやって来た時に、Beast Deckを返却して下さい。", "Beastのカードをすべて集めてデッキにしたところ、最初の八枚と同じ裏面をした九枚目のカードが不思議と現れた。そのカードには「これらのカードをDarkmoon Faireへ返せば、報われるであろう」と刻まれている。この市は数か月ごとにMulgoreとGoldshireに交互に立ち寄ると聞いているので、次にここへ来るまで待たなければならない。", "おやまあ。", "獣のデッキを揃えたのですね。これを我らの元へ返してくれた行いは、Darkmoon Faireとの繋がりを作り、末永く記憶されることでしょう。ほんの感謝の印に、強力なDarkmoonのカードの中から一枚をプレゼントさせて下さい。", 0x63de7a0d, 0x62dda1b1, 0x405afcfa, 0x9e26ead5, 0x5dda3bb5, "....." },
  [7908] = { "Arena Master", "Stranglethorn ArenaのShort John Mithrilと話す。", "アリーナの達人になるってのは、こんなもんじゃないはずだ！ Gurubashiでこの催しを仕切ってる海賊なら知ってるかもしれない！", nil, nil, 0x11d885c3, 0x6414b72c, 0x84414394, nil, nil, "...mm" },
  [7926] = { "Darkmoon Faire", "Free Ticket VoucherをGelvas Grimgateに届けて下さい。彼はDarkmoon Faire carnivalの場所にいます。", "Darkmoon Faireがやって来たよ! Darkmoon Faireが町へ来たら、そのすべての不思議と熱狂を体験していってくれ!\n\n今すぐやるなら、この引換証を無料の賞品チケットに交換できるよ! 祭り会場にいるGelvas Grimgateに引換証を持って行くだけだ。\n\nちょうど今、Darkmoon FaireはMulgoreのThunder Bluffのすぐ外でやってるよ。この機会を逃すな! 今日行け!", "はい、友よ、何かご用ですか? 引き換えが必要なvoucherをお持ちですか?", "Darkmoon Faireへようこそ! この引換証は5枚分だね、ああ、チケット5枚だよ!\n\nチケットを貯めたら、貴重な賞品と引き替えるためにオレに話しかけるんだぞ。もっとチケットを手に入れれば、もっと賞品が獲得できるんだ。頑張れよ!", 0x81e45326, 0x59d160bd, 0x3d4daeaf, 0x08ce32b9, 0xf62b21ee, "....." },
  [7927] = { "Darkmoon Portals Deck", "Darkmoon Faireが町へやって来た時に、Portals Deckを返却して下さい。", "Portalのカードをすべて集めてデッキにしたところ、最初の八枚と同じ裏面をした九枚目のカードが不思議と現れた。そのカードには「これらのカードをDarkmoon Faireへ返せば、報われるであろう」と刻まれている。この市は数か月ごとにMulgoreとGoldshireに交互に立ち寄ると聞いているので、次にここへ来るまで待たなければならない。", "deck of portalsを揃えたようですね! おめでとうございます!", "門のデッキを揃えたのですね。これを我らの元へ返してくれた行いは、Darkmoon Faireとの繋がりを作り、末永く記憶されることでしょう。ほんの感謝の印に、強力なDarkmoonのカードの中から一枚をプレゼントさせて下さい。", 0xa0956489, 0xff866ea6, 0x114b9c81, 0x38992949, 0x45adf59a, "....." },
  [7928] = { "Darkmoon Warlords Deck", "Darkmoon Faireが町へやって来た時に、Warlords Deckを返却して下さい。", "Warlordのカードをすべて集めてデッキにしたところ、最初の八枚と同じ裏面をした九枚目のカードが不思議と現れた。そのカードには「これらのカードをDarkmoon Faireへ返せば、報われるであろう」と刻まれている。この市は数か月ごとにMulgoreとGoldshireに交互に立ち寄ると聞いているので、次にここへ来るまで待たなければならない。", "deck of warlordsを揃えたようですね! おめでとうございます!", "将軍のデッキを揃えたのですね。これを我らの元へ返してくれた行いは、Darkmoon Faireとの繋がりを作り、末永く記憶されることでしょう。ほんの感謝の印に、強力なDarkmoonのカードの中から一枚をプレゼントさせて下さい。", 0xe25ce5cf, 0xb6535fe4, 0x79c29624, 0x04e4adf5, 0x9d09863b, "....." },
  [7929] = { "Darkmoon Elementals Deck", "Darkmoon Faireが町へやって来た時に、Elementals Deckを返却して下さい。", "Elementalのカードをすべて集めてデッキにしたところ、最初の八枚と同じ裏面をした九枚目のカードが不思議と現れた。そのカードには「これらのカードをDarkmoon Faireへ返せば、報われるであろう」と刻まれている。この市は数か月ごとにMulgoreとGoldshireに交互に立ち寄ると聞いているので、次にここへ来るまで待たなければならない。", "deck of elementalsを揃えたようですね! おめでとうございます!", "精霊のデッキを揃えたのですね。これを我らの元へ返してくれた行いは、Darkmoon Faireとの繋がりを作り、末永く記憶されることでしょう。ほんの感謝の印に、強力なDarkmoonのカードの中から一枚をプレゼントさせて下さい。", 0x31989af8, 0xfea6f677, 0x6e234ab1, 0xc43ece46, 0xdac1d961, "....." },
  [7938] = { "運命があなたを待っている……", "WestfallのDeadminesへ行き、宝を見つけて下さい。", "「あなたの幸運はDeadminesの中で待っている。」\n\nSaygeに手渡された運勢の札は、触れるとほんのりと温かい。しっかりと握りしめると、Westfallの廃墟となった村Moonbrookの中にあるDeadminesの光景が見えてくる。その光景にさらに意識を集中すると、曲がりくねった通路をたどって、きらめくポータルへとたどり着く……鉱山そのものの中心へと通じるポータルだ。そこを通り抜けると、どこからともなく奇妙な宝箱が現れる。", "この箱は、あなたが幻視で見たものに似ている……", "木箱を素早く探ると、鍵付きの箱が現れた! 宝を見つけることができたようだ!", 0xd4d31135, 0x0a114641, 0xb9905b2d, 0x0f89f811, 0x4ff8a559, "....." },
  [7944] = { "運命があなたを待っている……", "BarrensのWailing Cavernsへ行き、宝を見つけて下さい。", "「Wailing Cavernsに運命が待っている」\n\n占い師Saygeが手渡した物は、かすかな温もりを感じさせた。それをしっかり握ると、BarrensのCrossroadsを南西に行ったところにある洞窟の光景が見えた。その光景に目をこらすと、ちらちらと光る入り口に着くまで曲がりくねった道を進んだ……その入り口は洞窟そのものの中心へと続いている。中へ足を踏み入れると、どこからともなく奇妙な木箱が現れた。", "この箱は、あなたが幻視で見たものに似ている……", "木箱を素早く探ると、鍵付きの箱が現れた! 宝を見つけることができたようだ!", 0xd4d31135, 0x0ecaa544, 0x3a54e251, 0x0f89f811, 0x4ff8a559, "....." },
  [7946] = { "Jubjubの子", nil, nil, "Jubjubが迷子じゃなくなって本当にうれしいわ。あの子はDark Iron aleが大好きで、私が切らしちゃったら……もっと探しに逃げ出しちゃったの!\n\nJubjubが戻ってきた今、aleをできるだけたくさん手に入れたいの! もう二度と逃げ出してほしくないもの!\n\nDark Iron Aleを持ってない? 持ってたら、ジョッキ一杯とJubjubのカエルの卵をひとつ交換してあげるわ……", "ありがとう、{name}。さあ卵だよ! 孵化の準備ができるまでもうしばらくかかるけど、孵化したらすごいペットが手に入るんだよ!", 0xad05c1dd, nil, nil, 0x09b8849d, 0xb8311bf6, ".mm.." },
  [7961] = { "ウサギどもめ！", "ウサギを5匹倒し、Designer Islandの炉のそばにいるJon LeCraftのところへ戻る。", "このウサギどもは手がつけられないほど繁殖している。何か手を打たねば！\n\n助けてくれ、{name}。頼れるのはお前だけだ。", nil, nil, 0x26e1428c, 0x7c67e5a2, 0x62029839, nil, nil, "...mm" },
  [7962] = { "Wabbitの毛皮", "LeCrafty Rabbit Peltを3枚、Jon LeCraftのところへ持って行く。", "LeCrafty rabbit peltsが欲しい。LeCrafty Rabbitsから取ってきてくれ。\n\nこれは大事なことなんだ！", nil, nil, 0x1ebd053c, 0xfd9305aa, 0x7ff5eaf6, nil, nil, "...mm" },
})
